// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {TrailsPdas} from "../src/TrailsPdas.sol";
import {ILocalAdapter} from "../src/interfaces/ILocalAdapter.sol";
import {IBridgeAdapter} from "../src/interfaces/IBridgeAdapter.sol";
import {RouteScopeBase} from "../src/scope/RouteScopeBase.sol";
import {RouteScopeStorage} from "../src/scope/RouteScopeStorage.sol";

/// @title TrailsPdasEvm
/// @author Agustin Aguilar
/// @notice Cancun / EVM deployment of TrailsPdas. It inherits all route logic and types unchanged
/// and overrides only the inbox-callback scope primitives to use EIP-1153 transient storage, which
/// is cheaper than ordinary storage and self-clears at the end of every transaction.
/// @dev Kept under `cancun/` (outside `./src`) so that TronBox and the Shanghai Foundry profile —
/// which cannot compile transient storage — never see this file. The storage slots declared by the
/// inherited RouteScopeStorage backend are never written here, so they carry no runtime cost.
contract TrailsPdasEvm is TrailsPdas {
  /// @dev Active inbox for the current route. The compiler assigns this its own transient slot.
  address private transient _scopeInboxT;

  /// @dev Route generation within the current transaction, bumped by every `_clearRouteScope`. Asset
  /// markings are keyed by it, so closing a scope invalidates all of its markings at once.
  uint256 private transient _scopeEpochT;

  /// @dev Namespace mixed into per-token asset slots so transient membership entries can never
  /// collide with the `_scopeInboxT` / `_scopeEpochT` slots or any future transient value-type variable.
  bytes32 private constant _ASSET_NAMESPACE = keccak256("trails.routescope.asset.v1");

  /// @param _initialAdmin Initial default admin
  /// @param _depositFeeCollector Initial non-zero recipient of deposit fees
  /// @param _initialLocalAdapters Initially registered local adapters
  /// @param _initialBridgeAdapters Initially registered bridge adapters
  constructor(
    address _initialAdmin,
    address _depositFeeCollector,
    ILocalAdapter[] memory _initialLocalAdapters,
    IBridgeAdapter[] memory _initialBridgeAdapters
  ) TrailsPdas(_initialAdmin, _depositFeeCollector, _initialLocalAdapters, _initialBridgeAdapters) {}

  function _setActiveInbox(address _inbox) internal override(RouteScopeBase, RouteScopeStorage) {
    _scopeInboxT = _inbox;
  }

  function _activeInbox() internal view override(RouteScopeBase, RouteScopeStorage) returns (address) {
    return _scopeInboxT;
  }

  function _markRouteAsset(address _token) internal override(RouteScopeBase, RouteScopeStorage) {
    if (_token == address(0)) {
      return;
    }

    bytes32 slot = _assetSlot(_scopeInboxT, _token);
    assembly ("memory-safe") {
      tstore(slot, 1)
    }
  }

  function _isRouteAsset(address _token) internal view override(RouteScopeBase, RouteScopeStorage) returns (bool) {
    bytes32 slot = _assetSlot(_scopeInboxT, _token);
    uint256 marked;
    assembly ("memory-safe") {
      marked := tload(slot)
    }
    return marked != 0;
  }

  /// @dev Resets the active inbox and bumps the route generation. Asset markings are not
  /// individually erased; they are keyed by (generation, inbox, token) (see `_assetSlot`), so once
  /// the generation moves every marking of the closed scope becomes unreachable. A later route in
  /// the same transaction starts with an empty asset set even when it runs on the same inbox, which
  /// matches the storage backend's explicit clear. Transient storage additionally self-clears at the
  /// end of the transaction.
  function _clearRouteScope() internal override(RouteScopeBase, RouteScopeStorage) {
    _scopeInboxT = address(0);
    unchecked {
      _scopeEpochT = _scopeEpochT + 1;
    }
  }

  function _assetSlot(address _inbox, address _token) private view returns (bytes32) {
    return keccak256(abi.encode(_ASSET_NAMESPACE, _scopeEpochT, _inbox, _token));
  }
}

