// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {TrailsPdasGovernor} from "./TrailsPdasGovernor.sol";
import {ITrailsPdasGoverned} from "./interfaces/ITrailsPdasGoverned.sol";

/// @title Access
/// @author Agustin Aguilar
/// @notice Route-side access state: the current default admin, flat role membership, and the
/// modifiers the entry points check.
/// @dev Role administration (OpenZeppelin two-step default admin transfer, grant/revoke, member
/// enumeration, `configurationHash`) lives in the `TrailsPdasGovernor` satellite this constructor
/// deploys, and the governor is the only address allowed to write the state kept here. The split is
/// an EIP-170 measure: that suite is cold-path code worth ~3.4 KB of route runtime, while keeping
/// membership in route storage leaves the hot-path `onlyExecutor` / `onlyAdmin` checks as plain
/// storage reads with no external call. See ARCHITECTURE.md, "The `TrailsPdasGovernor` satellite".
abstract contract Access {
  bytes32 public constant DEFAULT_ADMIN_ROLE = 0x00;
  bytes32 public constant EXECUTOR_ROLE = keccak256("EXECUTOR_ROLE");
  bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
  bytes32 public constant UNPAUSER_ROLE = keccak256("UNPAUSER_ROLE");

  event RoleSet(bytes32 indexed _role, address indexed _account, bool _granted);
  event DefaultAdminSet(address indexed _admin);

  /// @dev Same signature as OpenZeppelin's `IAccessControl` error, so callers keep one selector.
  error AccessControlUnauthorizedAccount(address account, bytes32 neededRole);
  error UnauthorizedGovernor(address _sender);

  /// @dev Deployed by this constructor rather than configured, so its code is pinned by the route's
  /// creation code (see `SolanaCrypto` for the same reasoning).
  TrailsPdasGovernor private immutable GOVERNOR;

  address private _defaultAdmin;
  mapping(bytes32 role => mapping(address account => bool granted)) private _roles;

  /// @param _initialAdmin Initial default admin, seeded here and in the governor
  constructor(address _initialAdmin) {
    GOVERNOR = new TrailsPdasGovernor(_initialAdmin, ITrailsPdasGoverned(address(this)));
    _defaultAdmin = _initialAdmin;
  }

  /// @notice The governance satellite this deployment created for itself.
  /// @dev Role administration (`grantRole`, `beginDefaultAdminTransfer`, …) and `getRoleMembers`
  /// are called on this address. Exposed so deploy tooling can verify its code against the expected
  /// build.
  function governor() external view returns (TrailsPdasGovernor) {
    return GOVERNOR;
  }

  function _governor() internal view returns (TrailsPdasGovernor) {
    return GOVERNOR;
  }

  /// @notice Current default admin, mirrored from the governor.
  function defaultAdmin() public view returns (address) {
    return _defaultAdmin;
  }

  /// @notice True when `_account` holds `_role`. `DEFAULT_ADMIN_ROLE` is single-holder and resolves to
  /// the current default admin.
  function hasRole(bytes32 _role, address _account) public view returns (bool) {
    if (_role == DEFAULT_ADMIN_ROLE) {
      return _account != address(0) && _account == _defaultAdmin;
    }
    return _roles[_role][_account];
  }

  /// @notice Mirrors a non-admin role change. Governor only.
  function setRole(bytes32 _role, address _account, bool _granted) external {
    _checkGovernor();
    _setRole(_role, _account, _granted);
  }

  /// @dev Flat role write; the governor is the only production caller (through `setRole`).
  function _setRole(bytes32 _role, address _account, bool _granted) internal {
    _roles[_role][_account] = _granted;
    emit RoleSet(_role, _account, _granted);
  }

  /// @notice Mirrors the current default admin. Governor only.
  function setDefaultAdmin(address _admin) external {
    _checkGovernor();
    _defaultAdmin = _admin;
    emit DefaultAdminSet(_admin);
  }

  function _checkGovernor() private view {
    if (msg.sender != address(GOVERNOR)) {
      revert UnauthorizedGovernor(msg.sender);
    }
  }

  modifier onlyAdmin() {
    _checkAdmin();
    _;
  }

  function _checkAdmin() private view {
    if (msg.sender != _defaultAdmin) {
      revert AccessControlUnauthorizedAccount(msg.sender, DEFAULT_ADMIN_ROLE);
    }
  }

  modifier onlyExecutor() {
    _checkRoleOrAdmin(EXECUTOR_ROLE);
    _;
  }

  modifier onlyPauser() {
    _checkRoleOrAdmin(PAUSER_ROLE);
    _;
  }

  modifier onlyUnpauser() {
    _checkRoleOrAdmin(UNPAUSER_ROLE);
    _;
  }

  function _checkRoleOrAdmin(bytes32 _role) internal view {
    if (!_roles[_role][msg.sender] && msg.sender != _defaultAdmin) {
      revert AccessControlUnauthorizedAccount(msg.sender, _role);
    }
  }
}

