// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";

import {Inboxes} from "./Inboxes.sol";

/// @title Deposit
/// @author Michael Standen
/// @notice Helpers for pulling ERC-20 deposits into an inbox, optionally using ERC-2612 permits
abstract contract Deposit is Inboxes {
  /// @notice ERC-2612 permit relayed by the executor. `deadline == 0` skips permit (allowance already set).
  /// @dev `signature` is 65 bytes `r || s || v`, matching Trails API `ComposeERC2612Permit`.
  struct ERC2612Permit {
    uint256 value;
    uint256 deadline;
    bytes signature;
  }

  /// @notice Optional ERC-20 pull executed immediately before route operations
  /// @dev A zero `_from` skips the pull. Native value is not supported.
  struct Pull {
    address token;
    address from;
    ERC2612Permit permit;
    uint256 feeAmount;
  }

  /// @notice Recipient of deposit fees
  /// @dev Set at construction and only by the admin afterwards; executors cannot redirect fees.
  address public depositFeeCollector;

  event DepositFeeCollectorSet(address indexed _depositFeeCollector);

  error NativePullUnsupported();
  error PullDepositZeroAmount(address _token, address _from);
  error PullDepositFailed(address _token, address _from, address _to, uint256 _amount);
  error InvalidPermitSignature(uint256 _length);
  error ZeroAddressFeeCollectorNotAllowed();

  /// @param _depositFeeCollector Initial non-zero recipient of deposit fees
  constructor(address _depositFeeCollector) {
    _setDepositFeeCollector(_depositFeeCollector);
  }

  /// @notice Sets the recipient of deposit fees
  /// @param _depositFeeCollector New non-zero recipient
  function setDepositFeeCollector(address _depositFeeCollector) external onlyAdmin {
    _setDepositFeeCollector(_depositFeeCollector);
  }

  function _setDepositFeeCollector(address _depositFeeCollector) private {
    if (_depositFeeCollector == address(0)) {
      revert ZeroAddressFeeCollectorNotAllowed();
    }

    depositFeeCollector = _depositFeeCollector;

    emit DepositFeeCollectorSet(_depositFeeCollector);
  }

  /// @notice Pulls all available `_token` from `_from`, optionally relaying an ERC-2612 permit
  /// @dev After relaying a permit with the inbox as spender, the gross pull is the lesser of
  /// `_from`'s balance and the inbox's allowance. `_feeAmount` is paid to `depositFeeCollector`
  /// and the remainder is deposited into `_inbox`. The caller bounds the fee against the gross.
  /// Fee-on-transfer tokens are not supported; amounts are nominal.
  /// @param _inbox Inbox that spends the allowance and receives the net deposit
  /// @param _token ERC-20 token to pull
  /// @param _from Account providing the tokens
  /// @param _permit ERC-2612 permit to relay; a zero deadline skips the permit call, and a failed permit
  /// is tolerated when the inbox allowance already covers `_permit.value`
  /// @param _feeAmount Fee deducted from the gross pull
  /// @return _result Result bytes from the transfer into the inbox
  /// @return _grossPulled Total moved out of `_from`, including `_feeAmount`
  function _pullDeposit(
    address _inbox,
    address _token,
    address _from,
    ERC2612Permit calldata _permit,
    uint256 _feeAmount
  ) internal returns (bytes memory _result, uint256 _grossPulled) {
    if (_token == address(0)) {
      revert NativePullUnsupported();
    }

    if (_permit.deadline != 0) {
      _relayPermit(_inbox, _token, _from, _permit);
    }

    // Read the post-permit state because the token is authoritative for both the available balance
    // and the allowance granted to the inbox.
    _grossPulled = _availableToPull(_inbox, _token, _from);
    if (_grossPulled <= _feeAmount) {
      revert PullDepositZeroAmount(_token, _from);
    }

    if (_feeAmount != 0) {
      _inboxTransferFrom(_inbox, _token, _from, depositFeeCollector, _feeAmount);
    }
    _result = _inboxTransferFrom(_inbox, _token, _from, _inbox, _grossPulled - _feeAmount);
  }

  /// @dev Anyone can submit a public permit to the token first, which consumes its nonce and makes
  /// the relayed call revert. The permit's effect is what matters, so a failed permit is tolerated
  /// when the inbox allowance already covers `_permit.value`; otherwise the permit revert bubbles.
  function _relayPermit(address _inbox, address _token, address _from, ERC2612Permit calldata _permit) private {
    (uint8 v, bytes32 r, bytes32 s) = _splitPermitSignature(_permit.signature);
    (bool success, bytes memory result) = _trySendInboxTransaction(
      _inbox, _token, 0, abi.encodeCall(IERC20Permit.permit, (_from, _inbox, _permit.value, _permit.deadline, v, r, s))
    );
    if (success || IERC20(_token).allowance(_from, _inbox) >= _permit.value) {
      return;
    }

    assembly ("memory-safe") {
      revert(add(result, 0x20), mload(result))
    }
  }

  function _availableToPull(address _inbox, address _token, address _from) private view returns (uint256) {
    uint256 balance = IERC20(_token).balanceOf(_from);
    uint256 allowance = IERC20(_token).allowance(_from, _inbox);

    return balance < allowance ? balance : allowance;
  }

  function _inboxTransferFrom(address _inbox, address _token, address _from, address _to, uint256 _amount)
    private
    returns (bytes memory _result)
  {
    _result = _sendInboxTransaction(_inbox, _token, 0, abi.encodeCall(IERC20.transferFrom, (_from, _to, _amount)));
    if (_result.length != 0 && !abi.decode(_result, (bool))) {
      revert PullDepositFailed(_token, _from, _to, _amount);
    }
  }

  function _splitPermitSignature(bytes calldata _signature) private pure returns (uint8 v, bytes32 r, bytes32 s) {
    if (_signature.length != 65) {
      revert InvalidPermitSignature(_signature.length);
    }

    assembly ("memory-safe") {
      r := calldataload(_signature.offset)
      s := calldataload(add(_signature.offset, 32))
      v := byte(0, calldataload(add(_signature.offset, 64)))
    }
    if (v < 27) {
      v += 27;
    }
  }
}

src/Destination.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {Inboxes} from "./Inboxes.sol";
import {InboxConfig} from "./libraries/InboxConfig.sol";
import {InboxTokenTransfer} from "./libraries/InboxTokenTransfer.sol";

/// @title Destination
/// @author Agustin Aguilar, Michael Standen
/// @notice Helpers for delivering inbox balances to their configured destination
abstract contract Destination is Inboxes {
  uint256 private constant DESTINATION_CALLDATA_HEADER_LENGTH = 21;

  /// @notice How non-empty destination calldata delivers the configured asset before invoking its call.
  enum DestinationMode {
    /// @notice Transfer the asset to `destinationTo`, then call the encoded target with zero value.
    TransferAndCall,
    /// @notice Approve `destinationTo`, call the encoded target, then clear the ERC-20 allowance.
    ApproveAndCall,
    /// @notice Call the encoded target with the full native balance as value.
    NativeValueAndCall
  }

  error InvalidDestinationCalldata(uint256 _length);
  error InvalidDestinationMode(uint8 _mode);
  error InvalidDestinationModeForToken(DestinationMode _mode, address _token);
  error DestinationTransferFailed(address _token, address _destination, uint256 _amount);
  error DestinationApprovalFailed(address _token, address _spender, uint256 _amount);
  error UnauthorizedDestinationCaller(address _sender);

  event DustRefunded(address indexed _inbox, address indexed _owner, address indexed _token, uint256 _amount);
  event DestinationDelivered(
    bytes32 indexed _configurationRoot,
    address indexed _inbox,
    bytes32 _destinationTo,
    bytes32 _destinationToken,
    uint256 _amount
  );
  /// @notice Emitted instead of `DestinationDelivered` when delivery failed and the asset went to the PDA owner
  event DestinationRecovered(
    bytes32 indexed _configurationRoot,
    address indexed _inbox,
    address _owner,
    bytes32 _destinationToken,
    uint256 _amount
  );

  /// @notice Delivers the destination asset, falling back to the PDA owner if delivery fails
  /// @return _result Result bytes from the last inbox action
  /// @return _amount Asset amount delivered or recovered
  function _executeDestination(
    bytes32 _configurationRoot,
    address _inbox,
    bytes32 _destination,
    bytes32 _token,
    bytes calldata _destinationCalldata,
    address _owner
  ) internal returns (bytes memory _result, uint256 _amount) {
    try this.deliverDestination(_inbox, _destination, _token, _destinationCalldata) returns (
      bytes memory result, uint256 amount
    ) {
      emit DestinationDelivered(_configurationRoot, _inbox, _destination, _token, amount);
      return (result, amount);
    } catch {
      // Don't decode the revert reason: the destination is attacker-chosen and can return
      // unbounded data.
      (_result, _amount) = _transferDestinationAsset(_inbox, _owner, InboxConfig.bytes32ToAddress(_token));
      emit DestinationRecovered(_configurationRoot, _inbox, _owner, _token, _amount);
    }
  }

  /// @notice Delivers the inbox's configured destination asset
  /// @dev Only reachable from `_executeDestination`, which needs an external call to isolate failures.
  function deliverDestination(address _inbox, bytes32 _destination, bytes32 _token, bytes calldata _destinationCalldata)
    external
    returns (bytes memory _result, uint256 _amount)
  {
    if (msg.sender != address(this)) {
      revert UnauthorizedDestinationCaller(msg.sender);
    }
    address destination = InboxConfig.bytes32ToAddress(_destination);
    address token = InboxConfig.bytes32ToAddress(_token);

    if (_destinationCalldata.length == 0) {
      return _transferDestinationAsset(_inbox, destination, token);
    }

    (DestinationMode mode, address callTo) = _destinationCall(_destinationCalldata);
    bytes calldata callData = _destinationCalldata[DESTINATION_CALLDATA_HEADER_LENGTH:];

    if (mode == DestinationMode.TransferAndCall) {
      (_result, _amount) = _transferDestinationAsset(_inbox, destination, token);
      _result = _sendInboxTransaction(_inbox, callTo, 0, callData);
      return (_result, _amount);
    }

    if (mode == DestinationMode.ApproveAndCall) {
      if (token == address(0)) {
        revert InvalidDestinationModeForToken(mode, token);
      }
      _amount = IERC20(token).balanceOf(_inbox);
      _approveToken(_inbox, destination, token, _amount);
      _result = _sendInboxTransaction(_inbox, callTo, 0, callData);
      _approveToken(_inbox, destination, token, 0);
      return (_result, _amount);
    }

    if (mode == DestinationMode.NativeValueAndCall) {
      if (token != address(0)) {
        revert InvalidDestinationModeForToken(mode, token);
      }
      _amount = _inbox.balance;
      _result = _sendInboxTransaction(_inbox, callTo, _amount, callData);
      return (_result, _amount);
    }

    revert InvalidDestinationMode(uint8(mode));
  }

  function _transferDestinationAsset(address _inbox, address _destination, address _token)
    internal
    returns (bytes memory _result, uint256 _amount)
  {
    if (_token == address(0)) {
      return _transferNative(_inbox, _destination);
    }

    return _transferToken(_inbox, _destination, _token);
  }

  function _transferNative(address _inbox, address _destination)
    private
    returns (bytes memory _result, uint256 _amount)
  {
    _amount = _inbox.balance;
    if (_amount == 0) {
      return ("", 0);
    }

    _result = _sendInboxTransaction(_inbox, _destination, _amount, "");
  }

  function _transferToken(address _inbox, address _destination, address _token)
    private
    returns (bytes memory _result, uint256 _amount)
  {
    _amount = IERC20(_token).balanceOf(_inbox);
    if (_amount == 0) {
      return ("", 0);
    }
    _result = _sendInboxTransaction(_inbox, _token, 0, abi.encodeCall(IERC20.transfer, (_destination, _amount)));
    if (!InboxTokenTransfer.succeeded(_result, _token, _inbox, _amount, _amount)) {
      revert DestinationTransferFailed(_token, _destination, _amount);
    }
  }

  function _approveToken(address _inbox, address _spender, address _token, uint256 _amount) private {
    bytes memory result = _sendInboxTransaction(_inbox, _token, 0, abi.encodeCall(IERC20.approve, (_spender, _amount)));
    if (result.length != 0 && !abi.decode(result, (bool))) {
      revert DestinationApprovalFailed(_token, _spender, _amount);
    }
  }

  function _refundDust(address _inbox, address _owner, address[] calldata _tokens) internal {
    uint256 numTokens = _tokens.length;
    for (uint256 i = 0; i < numTokens; i++) {
      address token = _tokens[i];
      uint256 amount = _assetBalance(_inbox, token);
      if (amount == 0) {
        continue;
      }

      _transferDestinationAsset(_inbox, _owner, token);
      emit DustRefunded(_inbox, _owner, token, amount);
    }
  }

  function _assetBalance(address _inbox, address _token) private view returns (uint256) {
    if (_token == address(0)) {
      return _inbox.balance;
    }

    return IERC20(_token).balanceOf(_inbox);
  }

  function _destinationCall(bytes calldata _destinationCalldata)
    private
    pure
    returns (DestinationMode _mode, address _callTo)
  {
    if (_destinationCalldata.length < DESTINATION_CALLDATA_HEADER_LENGTH) {
      revert InvalidDestinationCalldata(_destinationCalldata.length);
    }

    uint8 rawMode;
    assembly ("memory-safe") {
      rawMode := byte(0, calldataload(_destinationCalldata.offset))
      _callTo := shr(96, calldataload(add(_destinationCalldata.offset, 1)))
    }
    if (rawMode > uint8(DestinationMode.NativeValueAndCall)) {
      revert InvalidDestinationMode(rawMode);
    }
    _mode = DestinationMode(rawMode);
  }
}

src/Inbox.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

/*
// Reference implementation, for documenting the hand-assembled runtime below.
//
// The real inbox has no ABI dispatcher and no malformed-payload guards. Creator
// calls are expected to use this calldata layout:
//
//   [0x00..0x1f] target, encoded as a uint160 in the low 20 bytes
//   [0x20..0x3f] value
//   [0x40..    ] calldata forwarded to target
//
// Any non-creator call succeeds immediately with empty return data. If the call
// carries ETH, that ETH remains in the inbox.
//
// contract InboxReference {
//   address immutable creator;
//
//   constructor(address _creator) payable {
//     creator = _creator;
//   }
//
//   fallback(bytes calldata payload) external payable returns (bytes memory result) {
//     if (msg.sender != creator) {
//       return "";
//     }
//
//     address target = address(uint160(uint256(bytes32(payload[0x00:0x20]))));
//     uint256 value = uint256(bytes32(payload[0x20:0x40]));
//     (bool success, bytes memory response) = target.call{value: value}(payload[0x40:]);
//
//     if (!success) {
//       assembly ("memory-safe") {
//         revert(add(response, 0x20), mload(response))
//       }
//     }
//
//     return response;
//   }
// }
//
//
// Deconstructed bytecode
// ----------------------
//
// creationCode(_creator) =
//   INIT_PREFIX ++ RUNTIME_PREFIX ++ bytes20(_creator) ++ RUNTIME_SUFFIX
//
// Constructor, 9 bytes:
//
//   60 3e       push1 0x3e        // [runtime_size]
//   80          dup1              // [runtime_size, runtime_size]
//   60 09       push1 0x09        // [runtime_offset, runtime_size, runtime_size]
//   5f          push0             // [0, runtime_offset, runtime_size, runtime_size]
//   39          codecopy          // [runtime_size]
//   5f          push0             // [0, runtime_size]
//   f3          return            // return(0, runtime_size)
//
// Runtime, 62 bytes:
//
//   33          caller            // [caller]
//   73 <creator>
//               push20 creator    // [creator, caller]
//   14          eq                // [caller == creator]
//   60 1b       push1 execute     // [execute, caller == creator]
//   57          jumpi             // []
//   00          stop              // Non-creator: accept ETH and return empty data.
// execute:
//   5b          jumpdest          // []
//   60 40       push1 0x40        // [0x40]
//   36          calldatasize      // [calldatasize, 0x40]
//   03          sub               // [calldatasize - 0x40]
//   80          dup1              // [data_size, data_size]
//   60 40       push1 0x40        // [0x40, data_size, data_size]
//   5f          push0             // [0, 0x40, data_size, data_size]
//   37          calldatacopy      // [data_size]
//                                  // memory[0:data_size] = calldata[0x40:]
//   5f          push0             // [0, data_size]
//   5f          push0             // [0, 0, data_size]
//   91          swap2             // [data_size, 0, 0]
//   5f          push0             // [0, data_size, 0, 0]
//   60 20       push1 0x20        // [0x20, 0, data_size, 0, 0]
//   35          calldataload      // [value, 0, data_size, 0, 0]
//   5f          push0             // [0, value, 0, data_size, 0, 0]
//   35          calldataload      // [target, value, 0, data_size, 0, 0]
//   5a          gas               // [gas, target, value, 0, data_size, 0, 0]
//   f1          call              // [success]
//   3d          returndatasize    // [returndata_size, success]
//   80          dup1              // [returndata_size, returndata_size, success]
//   5f          push0             // [0, returndata_size, returndata_size, success]
//   5f          push0             // [0, 0, returndata_size, returndata_size, success]
//   3e          returndatacopy    // [returndata_size, success]
//   90          swap1             // [success, returndata_size]
//   60 3b       push1 success     // [success_jumpdest, success, returndata_size]
//   57          jumpi             // [returndata_size]
//   5f          push0             // [0, returndata_size]
//   fd          revert            // revert(0, returndata_size)
// success:
//   5b          jumpdest          // [returndata_size]
//   5f          push0             // [0, returndata_size]
//   f3          return            // return(0, returndata_size)
*/

/// @title Inbox
/// @notice Hand-assembled inbox creation code.
library Inbox {
  bytes private constant INIT_PREFIX = hex"603e8060095f395ff3";
  bytes private constant RUNTIME_PREFIX = hex"3373";
  bytes private constant RUNTIME_SUFFIX =
    hex"14601b57005b604036038060405f375f5f915f6020355f355af13d805f5f3e90603b575ffd5b5ff3";

  function creationCode(address _creator) internal pure returns (bytes memory) {
    return abi.encodePacked(INIT_PREFIX, RUNTIME_PREFIX, bytes20(_creator), RUNTIME_SUFFIX);
  }

  function initCodeHash(address _creator) internal pure returns (bytes32) {
    return keccak256(creationCode(_creator));
  }
}

src/InboxRecovery.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

import {Inboxes} from "./Inboxes.sol";
import {InboxConfig} from "./libraries/InboxConfig.sol";

/// @title InboxRecoveryBase
/// @notice Owner-signed recovery of deterministic inboxes.
/// @dev An inbox address is counterfactual, so it can be funded before anything validates the config
/// behind it — and the funding chain is exactly where users pay in. Recovery therefore has to work for
/// every owner the config declares, in that owner's own key system, or a deposit made against a
/// config with no owner for the landing runtime is simply lost.
///
/// Two signature schemes cover the three owner slots:
///
/// - **secp256k1** (`owners.evm`, `owners.tron`) — an EIP-712 `InboxRecovery` under the
///   `TrailsPdasInbox` domain, verified in this contract.
/// - **ed25519** (`owners.solana`) — a printable-ASCII message signed by the Solana key, verified
///   through `SolanaCrypto` because the curve arithmetic does not fit in this contract's remaining
///   EIP-170 budget.
///
/// The local runtime's own owner has priority; a foreign owner is only accepted when no closer one is
/// configured. That mirrors the SVM core, where a Solana-native owner keeps the native path and
/// `send_inbox_*_signed` is reserved for configs with no Solana owner at all.
abstract contract InboxRecoveryBase is Inboxes {
  bytes32 private constant EIP712_DOMAIN_TYPEHASH =
    keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");
  bytes32 private constant RECOVERY_DOMAIN_NAME_HASH = keccak256("TrailsPdasInbox");
  bytes32 private constant RECOVERY_DOMAIN_VERSION_HASH = keccak256("1");
  bytes32 private constant INBOX_RECOVERY_TYPEHASH =
    keccak256("InboxRecovery(bytes32 configurationRoot,address target,uint256 value,bytes data,uint256 nonce)");

  /// @notice Owner-signed arbitrary transaction to execute from a deterministic inbox.
  struct InboxRecovery {
    address target;
    uint256 value;
    bytes data;
    uint256 nonce;
  }

  /// @notice Emitted after an owner-signed recovery call succeeds. The signer is not logged: the root
  /// commits to the owners, and the priority rule above picks exactly one of them.
  event InboxRecovered(
    bytes32 indexed _configurationRoot, address indexed _inbox, address _target, uint256 _value, uint256 _nonce
  );

  error InvalidRecoveryNonce();
  error UnauthorizedRecoverySigner();

  /// @notice Next owner-signed recovery nonce for each configuration root.
  mapping(bytes32 configurationRoot => uint256 nonce) public recoveryNonces;

  /// @notice Executes an owner-signed arbitrary transaction from an inbox.
  /// @dev Any relayer may submit it: the signature — secp256k1 or ed25519, depending on which owner
  /// slots the config carries — binds the configuration root, target, native value, calldata and
  /// nonce, so the submitter chooses nothing.
  function selfRecover(InboxConfig.Config calldata _config, InboxRecovery calldata _recovery, bytes calldata _signature)
    external
    returns (bytes memory _result)
  {
    bytes32 configurationRoot = _configurationRoot(_config);
    uint256 expectedNonce = recoveryNonces[configurationRoot];
    if (_recovery.nonce != expectedNonce) {
      revert InvalidRecoveryNonce();
    }

    _requireRecoveryAuthorization(_config, configurationRoot, _recovery, _signature);

    // Increment before the inbox call. A target revert rolls this state change back atomically.
    recoveryNonces[configurationRoot] = expectedNonce + 1;
    address inbox = _requireInbox(configurationRoot);
    _result = _sendInboxTransaction(inbox, _recovery.target, _recovery.value, _recovery.data);
    emit InboxRecovered(configurationRoot, inbox, _recovery.target, _recovery.value, expectedNonce);
  }

  /// @dev Authorizes the recovery under whichever owner slot applies, or reverts.
  function _requireRecoveryAuthorization(
    InboxConfig.Config calldata _config,
    bytes32 _root,
    InboxRecovery calldata _recovery,
    bytes calldata _signature
  ) private view {
    address secpOwner = _recoverySecpOwner(_config);
    if (secpOwner != address(0)) {
      if (ECDSA.recoverCalldata(_selfRecoverDigest(_root, _recovery), _signature) != secpOwner) {
        revert UnauthorizedRecoverySigner();
      }

      return;
    }

    // No secp256k1 owner exists, so the inbox is only recoverable at all if a Solana owner signs for
    // it. The nonce is shared with the secp256k1 path, so the two schemes cannot replay each other.
    bytes32 solanaOwner = _config.owners.solana;
    if (solanaOwner == bytes32(0)) {
      _revertMissingRuntimeOwner(block.chainid, _localRuntime());
    }

    bool authorized = _solanaCrypto()
      .verifyInboxRecovery(
        solanaOwner, _root, _recovery.target, _recovery.value, keccak256(_recovery.data), _recovery.nonce, _signature
      );
    if (!authorized) {
      revert UnauthorizedRecoverySigner();
    }
  }

  /// @dev The secp256k1 owner that may authorize here: this runtime's slot first, the other runtime's
  /// as a fallback. Zero when the config declares neither, which hands over to the ed25519 path.
  function _recoverySecpOwner(InboxConfig.Config calldata _config) private view returns (address _owner) {
    bool isTron = _localRuntime() == Runtime.TVM;
    _owner = isTron ? _config.owners.tron : _config.owners.evm;
    if (_owner == address(0)) {
      _owner = isTron ? _config.owners.evm : _config.owners.tron;
    }
  }

  /// @dev Implemented by the route so its shared missing-owner error remains source-addressable.
  function _revertMissingRuntimeOwner(uint256 _chainId, Runtime _runtime) internal pure virtual;

  function _configurationRoot(InboxConfig.Config calldata _config) private pure returns (bytes32) {
    return InboxConfig.rootCalldata(_config);
  }

  function _selfRecoverDigest(bytes32 _root, InboxRecovery calldata _recovery) private view returns (bytes32) {
    bytes32 structHash = keccak256(
      abi.encode(
        INBOX_RECOVERY_TYPEHASH, _root, _recovery.target, _recovery.value, keccak256(_recovery.data), _recovery.nonce
      )
    );
    bytes32 domainSeparator = keccak256(
      abi.encode(
        EIP712_DOMAIN_TYPEHASH, RECOVERY_DOMAIN_NAME_HASH, RECOVERY_DOMAIN_VERSION_HASH, block.chainid, address(this)
      )
    );

    return keccak256(abi.encodePacked("\x19\x01", domainSeparator, structHash));
  }
}

