// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {Create2} from "@openzeppelin/contracts/utils/Create2.sol";

import {Inbox} from "./Inbox.sol";
import {Access} from "./Access.sol";
import {SolanaCrypto} from "./SolanaCrypto.sol";
import {ISolanaCrypto} from "./interfaces/ISolanaCrypto.sol";
import {EnumerableSet} from "./libraries/EnumerableSet.sol";
import {InboxAddress} from "./libraries/InboxAddress.sol";
import {InboxCall} from "./libraries/InboxCall.sol";
import {LocalRuntime} from "./libraries/LocalRuntime.sol";

/// @title Inboxes
/// @author Agustin Aguilar
/// @notice Counterfactual inbox creation and execution helpers
abstract contract Inboxes is Access {
  using EnumerableSet for EnumerableSet.Bytes32Set;

  /// @notice How a remote chain's counterfactual inbox address is computed.
  enum Runtime {
    Unset,
    EVM,
    TVM,
    SVM
  }

  /// @notice Per-destination description of how to compute the remote inbox address.
  /// @dev `params` is `abi.encode(address deployer)` for EVM and TVM, and
  /// `abi.encode(bytes32 program, bytes32 routePda)` for SVM. The Solana inbox PDA (and its
  /// canonical bump) is derived on-chain per configuration root, so no bump is configured.
  struct RemoteInbox {
    Runtime runtime;
    bytes params;
  }

  event LocalRuntimeDetected(Runtime indexed _runtime);
  event InboxCreated(bytes32 indexed _configurationRoot, address indexed _inbox);
  event RemoteInboxSet(uint256 indexed _chainId, Runtime indexed _runtime, bytes _params);
  event RemoteInboxCleared(uint256 indexed _chainId);
  event RemoteInboxFallbackSet(Runtime indexed _runtime, bytes _params);
  event RemoteInboxFallbackCleared();

  error InboxAlreadyDeployed(bytes32 _configurationRoot, address _inbox);
  error ZeroRemoteInboxDeployer();
  error ZeroSolanaInboxDerivation();
  error InvalidRemoteRuntime();
  error RemoteInboxNotSet(uint256 _chainId);

  mapping(uint256 chainId => RemoteInbox remoteInbox) private remoteInboxes;
  EnumerableSet.Bytes32Set private remoteInboxChainIds;
  RemoteInbox private fallbackRemoteInbox;

  /// @dev Resolved once, at construction, from the VM's own CREATE2 behaviour. It must never become
  /// mutable: it feeds counterfactual inbox address derivation, so changing it would re-derive every
  /// inbox address and orphan funds already sent to previously-published ones.
  bool private immutable IS_TRON_RUNTIME;

  /// @dev Solana PDA derivation and ed25519 verification, deployed by this constructor rather than
  /// configured. See `SolanaCrypto` for why it is not an argument: it decides where a bridge to
  /// Solana lands and whether a Solana owner's recovery signature is real, so its code has to be
  /// pinned by this contract's own creation code.
  ISolanaCrypto private immutable SOLANA_CRYPTO;

  constructor() {
    bool isTronRuntime = _detectLocalRuntime();
    IS_TRON_RUNTIME = isTronRuntime;
    SOLANA_CRYPTO = new SolanaCrypto();

    emit LocalRuntimeDetected(isTronRuntime ? Runtime.TVM : Runtime.EVM);
  }

  /// @notice The Solana primitives helper this deployment created for itself.
  /// @dev Exposed so deploy tooling can verify the satellite's code against the expected build.
  function solanaCrypto() external view returns (ISolanaCrypto) {
    return SOLANA_CRYPTO;
  }

  function _solanaCrypto() internal view returns (ISolanaCrypto) {
    return SOLANA_CRYPTO;
  }

  /// @notice The runtime this deployment resolved itself to at construction.
  /// @dev Exposed so deploy tooling can assert that every `setRemoteInbox(chainId, runtime, …)`
  /// entry agrees with what the router on `chainId` reports about itself, instead of both sides
  /// independently guessing.
  function localRuntime() external view returns (Runtime) {
    return _localRuntime();
  }

  /// @dev Runtime detection, isolated behind a `virtual` seam. Production deployments must use the
  /// probe; the seam exists only so tests can pin a runtime, since no EVM test VM can be made to
  /// derive CREATE2 addresses the way the TVM does.
  function _detectLocalRuntime() internal virtual returns (bool) {
    return LocalRuntime.detect();
  }

  function remoteInbox(uint256 _chainId) external view returns (RemoteInbox memory) {
    return remoteInboxes[_chainId];
  }

  function remoteInboxFallback() external view returns (RemoteInbox memory) {
    return fallbackRemoteInbox;
  }

  /// @notice Chain ids carrying an explicit remote inbox entry.
  /// @dev Enumeration for the governor's `configurationHash`; ordering is an implementation detail.
  function remoteInboxChains() external view returns (bytes32[] memory) {
    return remoteInboxChainIds.values();
  }

  function setRemoteInbox(uint256 _chainId, Runtime _runtime, bytes calldata _params) external onlyAdmin {
    _validateRemoteInbox(_runtime, _params);
    remoteInboxes[_chainId] = RemoteInbox({runtime: _runtime, params: _params});
    remoteInboxChainIds.add(bytes32(_chainId));
    emit RemoteInboxSet(_chainId, _runtime, _params);
  }

  function clearRemoteInbox(uint256 _chainId) external onlyAdmin {
    delete remoteInboxes[_chainId];
    remoteInboxChainIds.remove(bytes32(_chainId));
    emit RemoteInboxCleared(_chainId);
  }

  function setRemoteInboxFallback(Runtime _runtime, bytes calldata _params) external onlyAdmin {
    _validateRemoteInbox(_runtime, _params);
    fallbackRemoteInbox = RemoteInbox({runtime: _runtime, params: _params});
    emit RemoteInboxFallbackSet(_runtime, _params);
  }

  function clearRemoteInboxFallback() external onlyAdmin {
    delete fallbackRemoteInbox;
    emit RemoteInboxFallbackCleared();
  }

  function _validateRemoteInbox(Runtime _runtime, bytes calldata _params) private pure {
    if (_runtime == Runtime.EVM || _runtime == Runtime.TVM) {
      if (abi.decode(_params, (address)) == address(0)) {
        revert ZeroRemoteInboxDeployer();
      }
    } else if (_runtime == Runtime.SVM) {
      (bytes32 program, bytes32 routePda) = abi.decode(_params, (bytes32, bytes32));
      if (program == bytes32(0) || routePda == bytes32(0)) {
        revert ZeroSolanaInboxDerivation();
      }
    } else {
      revert InvalidRemoteRuntime();
    }
  }

  function _createInbox(bytes32 _configurationRoot) internal returns (address _inbox) {
    bytes memory code = Inbox.creationCode(address(this));

    _inbox = _inboxAddress(_configurationRoot);
    if (_inbox.code.length != 0) {
      revert InboxAlreadyDeployed(_configurationRoot, _inbox);
    }

    _inbox = Create2.deploy(msg.value, _configurationRoot, code);
    emit InboxCreated(_configurationRoot, _inbox);
  }

  function _sendInboxTransaction(address _inbox, address _target, uint256 _value, bytes memory _data)
    internal
    returns (bytes memory _result)
  {
    return InboxCall.sendTransaction(_inbox, _target, _value, _data);
  }

  function _trySendInboxTransaction(address _inbox, address _target, uint256 _value, bytes memory _data)
    internal
    returns (bool _success, bytes memory _result)
  {
    return InboxCall.trySendTransaction(_inbox, _target, _value, _data);
  }

  function _requireInbox(bytes32 _configurationRoot) internal returns (address _inbox) {
    _inbox = _inboxAddress(_configurationRoot);

    if (_inbox.code.length != 0) {
      return _inbox;
    }

    return _createInbox(_configurationRoot);
  }

  function _inboxAddress(bytes32 _configurationRoot) internal view returns (address _inbox) {
    bytes32 initCodeHash = Inbox.initCodeHash(address(this));
    if (_localRuntime() == Runtime.TVM) {
      return InboxAddress.computeTron(address(this), _configurationRoot, initCodeHash);
    }

    return InboxAddress.computeEvm(address(this), _configurationRoot, initCodeHash);
  }

  function _localRuntime() internal view returns (Runtime) {
    return IS_TRON_RUNTIME ? Runtime.TVM : Runtime.EVM;
  }

  function _remoteRuntime(uint256 _chainId) internal view returns (Runtime) {
    return _resolveRemoteInbox(_chainId).runtime;
  }

  function _remoteInboxRecipient(uint256 _chainId, bytes32 _configurationRoot) internal view returns (bytes32) {
    return _computeRemoteInboxRecipient(_resolveRemoteInbox(_chainId), _configurationRoot);
  }

  function _resolveRemoteInbox(uint256 _chainId) private view returns (RemoteInbox memory remote) {
    remote = remoteInboxes[_chainId];
    if (remote.runtime == Runtime.Unset) {
      remote = fallbackRemoteInbox;
      if (remote.runtime == Runtime.Unset) {
        revert RemoteInboxNotSet(_chainId);
      }
    }
  }

  function _computeRemoteInboxRecipient(RemoteInbox memory _remote, bytes32 _configurationRoot)
    private
    view
    returns (bytes32)
  {
    if (_remote.runtime == Runtime.EVM) {
      address deployer = abi.decode(_remote.params, (address));
      return _toBytes32(InboxAddress.computeEvm(deployer, _configurationRoot, Inbox.initCodeHash(deployer)));
    }

    if (_remote.runtime == Runtime.TVM) {
      address deployer = abi.decode(_remote.params, (address));
      return _toBytes32(InboxAddress.computeTron(deployer, _configurationRoot, Inbox.initCodeHash(deployer)));
    }

    if (_remote.runtime == Runtime.SVM) {
      (bytes32 program, bytes32 routePda) = abi.decode(_remote.params, (bytes32, bytes32));
      return SOLANA_CRYPTO.inboxProgramAddress(program, routePda, _configurationRoot);
    }

    revert InvalidRemoteRuntime();
  }

  function _toBytes32(address _account) private pure returns (bytes32) {
    return bytes32(uint256(uint160(_account)));
  }
}

src/RouteAccounting.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

import {Access} from "./Access.sol";
import {BridgeQuote} from "./interfaces/IBridgeAdapter.sol";
import {ExchangeRate, ISwapOracle, RouteAsset} from "./interfaces/ISwapOracle.sol";

/// @title RouteAccounting
/// @author Agustin Aguilar
/// @notice Balance snapshot and route valuation helpers
abstract contract RouteAccounting is Access {
  uint256 internal constant BPS_DENOMINATOR = 10_000;

  ISwapOracle public swapOracle;

  event SwapOracleSet(address indexed _swapOracle);

  error InvalidBridgeFeeTokenCount(uint256 _expected, uint256 _actual);
  error InvalidBridgeFeeToken(uint256 _index, address _expected, address _actual);
  error InvalidAssetIndex(uint256 _index, uint256 _numAssets);
  error InvalidAssetChain(uint256 _index, uint256 _expected, uint256 _actual);
  error InvalidAssetToken(uint256 _index, bytes32 _expected, address _actual);
  error SwapOracleNotSet();
  error InvalidOracleRateCount(uint256 _expected, uint256 _actual);
  error InvalidSwapOracleRate(uint256 _baseChainId, address _baseToken, uint256 _quoteChainId, address _quoteToken);
  error InsufficientRouteOutput(uint256 _required, uint256 _actual);
  error InvalidSlippageBps(uint256 _maxSlippageBps);
  error DepositFeeExceedsSlippage(uint256 _feeAmount, uint256 _grossPulled, uint256 _maxSlippageBps);
  error UndeclaredNativeEthSpent(address _inbox, uint256 _before, uint256 _after);
  error BridgeDebitMismatch(uint256 _index, uint256 _quoted, uint256 _measured);

  /// @notice Sets the oracle used to value route balance deltas
  function setSwapOracle(ISwapOracle _swapOracle) external onlyAdmin {
    swapOracle = _swapOracle;

    emit SwapOracleSet(address(_swapOracle));
  }

  function _validateBridgeRoute(
    RouteAsset[] calldata _assets,
    address _inbox,
    uint256[] memory _startingBalances,
    uint256[] memory _endingBalances,
    uint256 _tokenIn,
    uint256 _tokenOut,
    uint256[] calldata _feeTokens,
    BridgeQuote memory _quote,
    bytes calldata _oraclePayload,
    uint256 _maxSlippageBps
  ) internal view returns (uint256 _requiredOutput) {
    // Bridge quotes define the route's terminal debit and any required fee debits.
    // Fee tokens must match the declared asset order so accounting stays linear.
    uint256 numFees = _quote.fees.length;
    if (numFees != _feeTokens.length) {
      revert InvalidBridgeFeeTokenCount(numFees, _feeTokens.length);
    }

    uint256[] memory bridgeDebits = new uint256[](_assets.length);
    bridgeDebits[_tokenIn] = _quote.amountIn;

    for (uint256 i = 0; i < numFees; i++) {
      uint256 feeToken = _feeTokens[i];
      _requireLocalAsset(_assets, feeToken);
      if (_quote.fees[i].token != _assets[feeToken].token) {
        revert InvalidBridgeFeeToken(i, _quote.fees[i].token, _assets[feeToken].token);
      }

      bridgeDebits[feeToken] += _quote.fees[i].amount;
    }

    // The quote is the adapter's own account of what it spent, but the bridge call runs with the
    // route scope open, so the adapter or a protocol holding its temporary approval can move more
    // than it reports. Snapshot again after the bridge call and reject any asset that lost more than
    // its quoted debit; spending less (e.g. OFT dust) or gaining (refunds) keeps the quoted debit.
    _requireMeasuredDebitsWithinQuote(bridgeDebits, _endingBalances, _snapshotBalances(_inbox, _assets));

    uint256 inputValue =
      _inputValueAfterDebits(_assets, _startingBalances, _endingBalances, bridgeDebits, _tokenOut, _oraclePayload);
    _requiredOutput = _minimumOutput(inputValue, _maxSlippageBps);
    if (_requiredOutput > _quote.amountOut) {
      revert InsufficientRouteOutput(_requiredOutput, _quote.amountOut);
    }
  }

  function _requireMeasuredDebitsWithinQuote(
    uint256[] memory _quotedDebits,
    uint256[] memory _beforeBalances,
    uint256[] memory _afterBalances
  ) private pure {
    uint256 numAssets = _quotedDebits.length;
    for (uint256 i = 0; i < numAssets; i++) {
      if (_beforeBalances[i] > _afterBalances[i] && _beforeBalances[i] - _afterBalances[i] > _quotedDebits[i]) {
        revert BridgeDebitMismatch(i, _quotedDebits[i], _beforeBalances[i] - _afterBalances[i]);
      }
    }
  }

  function _validateDestinationRoute(
    RouteAsset[] calldata _assets,
    uint256[] memory _startingBalances,
    uint256[] memory _endingBalances,
    uint256 _destinationAsset,
    bytes calldata _oraclePayload,
    uint256 _maxSlippageBps
  ) internal view {
    // Destination execution pipes the full final asset balance. That balance is
    // counted as the route output, while any other leftovers are ignored.
    uint256[] memory destinationDebits = new uint256[](_assets.length);
    destinationDebits[_destinationAsset] = _endingBalances[_destinationAsset];

    uint256 inputValue = _inputValueAfterDebits(
      _assets, _startingBalances, _endingBalances, destinationDebits, _destinationAsset, _oraclePayload
    );
    uint256 outputAmount = _endingBalances[_destinationAsset];
    uint256 requiredOutput = _minimumOutput(inputValue, _maxSlippageBps);
    if (requiredOutput > outputAmount) {
      revert InsufficientRouteOutput(requiredOutput, outputAmount);
    }
  }

  function _snapshotBalances(address _inbox, RouteAsset[] calldata _assets)
    internal
    view
    returns (uint256[] memory _balances)
  {
    // Only current-chain balances are observable here. Remote-chain assets are
    // represented later by bridge quotes, not by live balance reads.
    uint256 numAssets = _assets.length;
    _balances = new uint256[](numAssets);
    for (uint256 i = 0; i < numAssets; i++) {
      if (_assets[i].chainId == block.chainid) {
        _balances[i] = _balanceOf(_inbox, _assets[i].token);
      }
    }
  }

  /// @notice True when the route declares the current chain's native token (address(0)) as an asset,
  /// so its balance deltas are already valued by the normal accounting. When false, native value is
  /// instead frozen across the adapter phase (see TrailsPdas), since native balance — unlike ERC-20s,
  /// which aren't enumerable — is always observable and so can be guarded unconditionally.
  function _nativeEthTracked(RouteAsset[] calldata _assets) internal view returns (bool) {
    uint256 numAssets = _assets.length;
    for (uint256 i = 0; i < numAssets; i++) {
      if (_assets[i].chainId == block.chainid && _assets[i].token == address(0)) {
        return true;
      }
    }
    return false;
  }

  function _requireLocalAsset(RouteAsset[] calldata _assets, uint256 _index) internal view {
    // Swap and fee operations can only touch the current-chain inbox. Remote
    // assets are valid as bridge outputs, but not as local spend inputs.
    _requireAsset(_assets, _index, block.chainid);
  }

  function _requireAsset(RouteAsset[] calldata _assets, uint256 _index, uint256 _chainId) internal pure {
    if (_index >= _assets.length) {
      revert InvalidAssetIndex(_index, _assets.length);
    }
    if (_assets[_index].chainId != _chainId) {
      revert InvalidAssetChain(_index, _chainId, _assets[_index].chainId);
    }
  }

  function _inputValueAfterDebits(
    RouteAsset[] calldata _assets,
    uint256[] memory _startingBalances,
    uint256[] memory _endingBalances,
    uint256[] memory _debits,
    uint256 _outputAsset,
    bytes calldata _oraclePayload
  ) private view returns (uint256 _inputValue) {
    // Core fairness rule: after removing planned debits, only balance decreases
    // are counted as inputs. Positive leftovers are not credited as output.
    uint256 numAssets = _assets.length;
    uint256 numOracleInputs;
    for (uint256 i = 0; i < numAssets; i++) {
      if (_assets[i].chainId != block.chainid) {
        continue;
      }

      uint256 terminalBalance = _endingBalances[i] > _debits[i] ? _endingBalances[i] - _debits[i] : 0;
      if (terminalBalance < _startingBalances[i]) {
        uint256 amountIn = _startingBalances[i] - terminalBalance;
        if (_isSameAsset(_assets[i], _assets[_outputAsset])) {
          _inputValue += amountIn;
        } else {
          numOracleInputs++;
        }
      }
    }

    if (numOracleInputs == 0) {
      return _inputValue;
    }

    (uint256[] memory oracleInputAssets, uint256[] memory oracleInputAmounts) =
      _oracleInputs(_assets, _startingBalances, _endingBalances, _debits, _outputAsset, numOracleInputs);

    // The payload is intentionally opaque here. Route accounting only asks for
    // rates in a concrete order and lets the configured oracle interpret it.
    ExchangeRate[] memory rates = _oracleRates(_assets, _outputAsset, oracleInputAssets, _oraclePayload);
    if (rates.length != numOracleInputs) {
      revert InvalidOracleRateCount(numOracleInputs, rates.length);
    }

    for (uint256 i = 0; i < numOracleInputs; i++) {
      if (rates[i].numerator == 0 || rates[i].denominator == 0) {
        uint256 inputAsset = oracleInputAssets[i];
        revert InvalidSwapOracleRate(
          _assets[inputAsset].chainId,
          _assets[inputAsset].token,
          _assets[_outputAsset].chainId,
          _assets[_outputAsset].token
        );
      }

      _inputValue += Math.mulDiv(oracleInputAmounts[i], rates[i].numerator, rates[i].denominator);
    }
  }

  /// @dev Second pass of `_inputValueAfterDebits`: collects the `_numOracleInputs` spent assets that
  /// need an oracle rate, in asset order. Split out to keep that frame shallow for `forge coverage`.
  function _oracleInputs(
    RouteAsset[] calldata _assets,
    uint256[] memory _startingBalances,
    uint256[] memory _endingBalances,
    uint256[] memory _debits,
    uint256 _outputAsset,
    uint256 _numOracleInputs
  ) private view returns (uint256[] memory _inputAssets, uint256[] memory _inputAmounts) {
    _inputAssets = new uint256[](_numOracleInputs);
    _inputAmounts = new uint256[](_numOracleInputs);
    uint256 numAssets = _assets.length;
    uint256 oracleInput;
    for (uint256 i = 0; i < numAssets; i++) {
      if (_assets[i].chainId != block.chainid) {
        continue;
      }

      uint256 terminalBalance = _endingBalances[i] > _debits[i] ? _endingBalances[i] - _debits[i] : 0;
      if (terminalBalance < _startingBalances[i] && !_isSameAsset(_assets[i], _assets[_outputAsset])) {
        _inputAssets[oracleInput] = i;
        _inputAmounts[oracleInput] = _startingBalances[i] - terminalBalance;
        oracleInput++;
      }
    }
  }

  function _oracleRates(
    RouteAsset[] calldata _assets,
    uint256 _outputAsset,
    uint256[] memory _inputAssets,
    bytes calldata _oraclePayload
  ) private view returns (ExchangeRate[] memory _rates) {
    ISwapOracle oracle = swapOracle;
    if (address(oracle) == address(0)) {
      revert SwapOracleNotSet();
    }

    return oracle.rates(address(this), _assets, _outputAsset, _inputAssets, _oraclePayload);
  }

  /// @notice Bounds a deposit fee using the inbox configuration's slippage tolerance
  /// @dev A deposit fee leaves the depositor before any route snapshot exists, so the balance-delta
  /// checks cannot observe it. Apply the configured basis points directly to each gross pull; the
  /// aggregate fee across repeated pulls is therefore bounded by the same fraction.
  /// @param _feeAmount Fee paid to the deposit fee collector
  /// @param _grossPulled Total moved out of the depositor, including `_feeAmount`
  /// @param _maxSlippageBps Slippage committed by the inbox configuration
  function _requireDepositFeeWithinSlippage(uint256 _feeAmount, uint256 _grossPulled, uint256 _maxSlippageBps)
    internal
    pure
  {
    if (_maxSlippageBps > BPS_DENOMINATOR) {
      revert InvalidSlippageBps(_maxSlippageBps);
    }

    if (_feeAmount * BPS_DENOMINATOR > _grossPulled * _maxSlippageBps) {
      revert DepositFeeExceedsSlippage(_feeAmount, _grossPulled, _maxSlippageBps);
    }
  }

  function _minimumOutput(uint256 _inputValue, uint256 _maxSlippageBps) private pure returns (uint256) {
    if (_maxSlippageBps > BPS_DENOMINATOR) {
      revert InvalidSlippageBps(_maxSlippageBps);
    }

    // Slippage is PDA configuration, not adapter policy. Round up so every
    // accepted route still satisfies the configured minimum output.
    return Math.mulDiv(_inputValue, BPS_DENOMINATOR - _maxSlippageBps, BPS_DENOMINATOR, Math.Rounding.Ceil);
  }

  function _isSameAsset(RouteAsset calldata _left, RouteAsset calldata _right) private pure returns (bool) {
    return _left.chainId == _right.chainId && _left.token == _right.token;
  }

  function _balanceOf(address _account, address _token) private view returns (uint256) {
    if (_token == address(0)) {
      return _account.balance;
    }

    return IERC20(_token).balanceOf(_account);
  }
}

src/RouteAdapters.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {Access} from "./Access.sol";
import {ILocalAdapter} from "./interfaces/ILocalAdapter.sol";
import {IBridgeAdapter, BridgeExecution, BridgeQuote} from "./interfaces/IBridgeAdapter.sol";
import {IInboxCallback} from "./interfaces/IInboxCallback.sol";
import {EnumerableSet} from "./libraries/EnumerableSet.sol";
import {InboxCall} from "./libraries/InboxCall.sol";
import {RouteScopeBase} from "./scope/RouteScopeBase.sol";

/// @title RouteAdapters
/// @author Agustin Aguilar
/// @notice Registry of trusted local and bridge adapters and their inbox callbacks
abstract contract RouteAdapters is Access, IInboxCallback, RouteScopeBase {
  using EnumerableSet for EnumerableSet.AddressSet;

  EnumerableSet.AddressSet private localAdapterSet;
  EnumerableSet.AddressSet private bridgeAdapterSet;

  event LocalAdapterAdded(address indexed _adapter);
  event LocalAdapterRemoved(address indexed _adapter);
  event BridgeAdapterAdded(address indexed _adapter);
  event BridgeAdapterRemoved(address indexed _adapter);

  error ZeroAddress();
  error AdapterAlreadyAdded(address _adapter);
  error AdapterNotFound(address _adapter);
  error UnauthorizedAdapter(address _adapter);
  error InboxCallOutOfScope(address _inbox);
  error UnaccountedAssetCall(address _token, bytes4 _selector);

  constructor(ILocalAdapter[] memory _initialLocalAdapters, IBridgeAdapter[] memory _initialBridgeAdapters) {
    for (uint256 i = 0; i < _initialLocalAdapters.length; i++) {
      address adapter = address(_initialLocalAdapters[i]);
      _addAdapter(localAdapterSet, adapter);
      emit LocalAdapterAdded(adapter);
    }

    for (uint256 i = 0; i < _initialBridgeAdapters.length; i++) {
      address adapter = address(_initialBridgeAdapters[i]);
      _addAdapter(bridgeAdapterSet, adapter);
      emit BridgeAdapterAdded(adapter);
    }
  }

  /// @notice Adds local operation adapters
  /// @param _adapters Adapter addresses to add
  function addLocalAdapters(ILocalAdapter[] calldata _adapters) external onlyAdmin {
    for (uint256 i = 0; i < _adapters.length; i++) {
      address adapter = address(_adapters[i]);
      _addAdapter(localAdapterSet, adapter);
      emit LocalAdapterAdded(adapter);
    }
  }

  /// @notice Removes local operation adapters
  /// @param _adapters Adapter addresses to remove
  function removeLocalAdapters(ILocalAdapter[] calldata _adapters) external onlyAdmin {
    for (uint256 i = 0; i < _adapters.length; i++) {
      address adapter = address(_adapters[i]);
      _removeAdapter(localAdapterSet, adapter);
      emit LocalAdapterRemoved(adapter);
    }
  }

  /// @notice Returns true when the adapter is authorized for local route operations
  function isLocalAdapter(address _adapter) external view returns (bool) {
    return localAdapterSet.contains(_adapter);
  }

  /// @notice Returns the local operation adapter at an enumerable index
  function localAdapterAt(uint256 _index) external view returns (address) {
    return localAdapterSet.at(_index);
  }

  function localAdapterCount() external view returns (uint256) {
    return localAdapterSet.length();
  }

  function localAdapters() external view returns (address[] memory) {
    return localAdapterSet.values();
  }

  /// @inheritdoc IInboxCallback
  function executeLocalInboxTransaction(address _inbox, address _target, uint256 _value, bytes calldata _data)
    external
    returns (bytes memory _result)
  {
    if (!localAdapterSet.contains(msg.sender)) {
      revert UnauthorizedAdapter(msg.sender);
    }

    _result = _executeInboxTransaction(_inbox, _target, _value, _data);
  }

  /// @inheritdoc IInboxCallback
  function executeBridgeInboxTransaction(address _inbox, address _target, uint256 _value, bytes calldata _data)
    external
    returns (bytes memory _result)
  {
    if (!bridgeAdapterSet.contains(msg.sender)) {
      revert UnauthorizedAdapter(msg.sender);
    }

    _result = _executeInboxTransaction(_inbox, _target, _value, _data);
  }

  function _executeInboxTransaction(address _inbox, address _target, uint256 _value, bytes calldata _data)
    private
    returns (bytes memory _result)
  {
    _assertInboxCallInScope(_inbox, _target, _data);
    _result = InboxCall.sendTransaction(_inbox, _target, _value, _data);
  }

  /// @notice Enforces that an inbox callback is in-scope for the active route and, for known
  /// asset-moving selectors (ERC-20/721/1155/777/1363 transfers and allowances, WETH and ERC-4626
  /// withdrawals), that the targeted token is a route-accounted asset.
  /// @dev This is only a selector denylist; registered adapters remain trusted for
  /// undeclared assets moved through any other selector.
  function _assertInboxCallInScope(address _inbox, address _target, bytes calldata _data) private view {
    if (_activeInbox() != _inbox) {
      revert InboxCallOutOfScope(_inbox);
    }

    if (_data.length >= 4 && _isAssetMovingSelector(bytes4(_data[:4])) && !_isRouteAsset(_target)) {
      revert UnaccountedAssetCall(_target, bytes4(_data[:4]));
    }
  }

  function _isAssetMovingSelector(bytes4 _selector) private pure returns (bool) {
    return _selector == IERC20.transfer.selector // 0xa9059cbb
      || _selector == IERC20.approve.selector // 0x095ea7b3
      || _selector == IERC20.transferFrom.selector // 0x23b872dd
      || _selector == 0x39509351 // increaseAllowance(address,uint256)
      || _selector == 0xd505accf // permit(address,address,uint256,uint256,uint8,bytes32,bytes32) EIP-2612
      || _selector == 0x8fcbaf0c // permit(address,address,uint256,uint256,bool,uint8,bytes32,bytes32) DAI
      || _selector == 0x42842e0e // safeTransferFrom(address,address,uint256) ERC-721
      || _selector == 0xb88d4fde // safeTransferFrom(address,address,uint256,bytes) ERC-721
      || _selector == 0xa22cb465 // setApprovalForAll(address,bool) ERC-721 / ERC-1155
      || _selector == 0xf242432a // safeTransferFrom(address,address,uint256,uint256,bytes) ERC-1155
      || _selector == 0x2eb2c2d6 // safeBatchTransferFrom(address,address,uint256[],uint256[],bytes) ERC-1155
      || _selector == 0x1296ee62 // transferAndCall(address,uint256) ERC-1363
      || _selector == 0x4000aea0 // transferAndCall(address,uint256,bytes) ERC-677 / ERC-1363
      || _selector == 0xd8fbe994 // transferFromAndCall(address,address,uint256) ERC-1363
      || _selector == 0xc1d34b89 // transferFromAndCall(address,address,uint256,bytes) ERC-1363
      || _selector == 0x3177029f // approveAndCall(address,uint256) ERC-1363
      || _selector == 0xcae9ca51 // approveAndCall(address,uint256,bytes) ERC-1363
      || _selector == 0x9bd9bbc6 // send(address,uint256,bytes) ERC-777
      || _selector == 0x62ad1b83 // operatorSend(address,address,uint256,bytes,bytes) ERC-777
      || _selector == 0x959b8c3f // authorizeOperator(address) ERC-777
      || _selector == 0x2e1a7d4d // withdraw(uint256) WETH
      || _selector == 0x205c2878 // withdrawTo(address,uint256) WETH10 / Arbitrum aeWETH
      || _selector == 0xba087652 // redeem(uint256,address,address) ERC-4626
      || _selector == 0xb460af94; // withdraw(uint256,address,address) ERC-4626
  }

  /// @notice Adapters only ever run inside the route scope of the inbox they operate on. The scope is
  /// opened by the route entry point; an adapter call never opens, reuses or widens a scope for a
  /// different inbox.
  function _requireAdapterInScope(address _inbox) private view {
    if (_inbox == address(0) || _activeInbox() != _inbox) {
      revert InboxCallOutOfScope(_inbox);
    }
  }

  function _executeLocalAdapter(
    ILocalAdapter _adapter,
    address _inbox,
    address _tokenIn,
    address _tokenOut,
    uint256 _amountIn,
    bytes memory _adapterCalldata
  ) internal returns (uint256 _amount) {
    address adapter = address(_adapter);
    if (!localAdapterSet.contains(adapter)) {
      revert AdapterNotFound(adapter);
    }

    _requireAdapterInScope(_inbox);

    _amount = _adapter.execute(_inbox, _tokenIn, _tokenOut, _amountIn, _adapterCalldata);
  }

  function _executeBridgeAdapter(
    IBridgeAdapter _adapter,
    address _inbox,
    address _tokenIn,
    address _tokenOut,
    uint256 _amountIn,
    uint256 _minAmountOut,
    uint256 _dstChainId,
    bytes32 _recipient,
    bytes memory _adapterCalldata
  ) internal returns (BridgeExecution memory _execution) {
    address adapter = address(_adapter);
    if (!bridgeAdapterSet.contains(adapter)) {
      revert AdapterNotFound(adapter);
    }

    _requireAdapterInScope(_inbox);

    _execution = _adapter.execute(
      _inbox, _tokenIn, _tokenOut, _amountIn, _minAmountOut, _dstChainId, _recipient, _adapterCalldata
    );
  }

  function _quoteBridgeAdapter(
    IBridgeAdapter _adapter,
    address _tokenIn,
    address _tokenOut,
    uint256 _amountIn,
    uint256 _minAmountOut,
    uint256 _dstChainId,
    bytes32 _recipient,
    bytes memory _adapterCalldata
  ) internal view returns (BridgeQuote memory _quote) {
    address adapter = address(_adapter);
    if (!bridgeAdapterSet.contains(adapter)) {
      revert AdapterNotFound(adapter);
    }

    return _adapter.quote(_tokenIn, _tokenOut, _amountIn, _minAmountOut, _dstChainId, _recipient, _adapterCalldata);
  }

  /// @notice Adds bridge adapters
  /// @param _adapters Adapter addresses to add
  function addBridgeAdapters(IBridgeAdapter[] calldata _adapters) external onlyAdmin {
    for (uint256 i = 0; i < _adapters.length; i++) {
      address adapter = address(_adapters[i]);
      _addAdapter(bridgeAdapterSet, adapter);
      emit BridgeAdapterAdded(adapter);
    }
  }

  /// @notice Removes bridge adapters
  /// @param _adapters Adapter addresses to remove
  function removeBridgeAdapters(IBridgeAdapter[] calldata _adapters) external onlyAdmin {
    for (uint256 i = 0; i < _adapters.length; i++) {
      address adapter = address(_adapters[i]);
      _removeAdapter(bridgeAdapterSet, adapter);
      emit BridgeAdapterRemoved(adapter);
    }
  }

  /// @notice Returns true when the adapter is authorized for bridge routes
  function isBridgeAdapter(address _adapter) external view returns (bool) {
    return bridgeAdapterSet.contains(_adapter);
  }

  /// @notice Returns the bridge adapter at an enumerable index
  function bridgeAdapterAt(uint256 _index) external view returns (address) {
    return bridgeAdapterSet.at(_index);
  }

  function bridgeAdapterCount() external view returns (uint256) {
    return bridgeAdapterSet.length();
  }

  function bridgeAdapters() external view returns (address[] memory) {
    return bridgeAdapterSet.values();
  }

  function _addAdapter(EnumerableSet.AddressSet storage _adapters, address _adapter) private {
    if (_adapter == address(0)) {
      revert ZeroAddress();
    }
    if (!_adapters.add(_adapter)) {
      revert AdapterAlreadyAdded(_adapter);
    }
  }

  function _removeAdapter(EnumerableSet.AddressSet storage _adapters, address _adapter) private {
    if (!_adapters.remove(_adapter)) {
      revert AdapterNotFound(_adapter);
    }
  }
}

