// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {ISolanaCrypto} from "./interfaces/ISolanaCrypto.sol";
import {Ed25519} from "./libraries/Ed25519.sol";
import {InboxAddress} from "./libraries/InboxAddress.sol";
import {SolanaPda} from "./libraries/SolanaPda.sol";

/// @title SolanaCrypto
/// @author Agustin Aguilar
/// @notice Solana's address derivation and signature scheme, executed on EVM/Tron.
/// @dev Two things the route needs are Solana-native and expensive in bytecode: `find_program_address`
/// (sha256 plus an ed25519 curve-membership test per bump) and ed25519 signature verification (a
/// software SHA-512 and two scalar multiplications, because no EVM chain has an ed25519 precompile).
/// Together they do not fit inside the route, which sits within a few hundred bytes of EIP-170 on the
/// Tron profile.
///
/// So they live here, and every route deploys its own copy **from its constructor**:
///
/// - the code is committed by the route's creation code, so it is not a trusted deployment parameter.
///   That matters: this contract decides where a bridge to Solana lands funds, and whether a Solana
///   owner's recovery signature is genuine. A settable address would put both under the admin's
///   control;
/// - the route's init code stays identical across chains, which is what keeps one route address (and
///   therefore one counterfactual inbox address per config) valid everywhere.
///
/// It is stateless and every entry point is `view`.
contract SolanaCrypto is ISolanaCrypto {
  /// @dev First line of every recovery message. Version it here, not in a separate field, so the
  /// signer reads the schema version in the same glance as the intent.
  string private constant RECOVERY_MESSAGE_HEADER = "Trails PDA inbox recovery v1";
  bytes16 private constant HEX_DIGITS = "0123456789abcdef";

  /// @inheritdoc ISolanaCrypto
  function inboxProgramAddress(bytes32 _program, bytes32 _routePda, bytes32 _configurationRoot)
    external
    view
    returns (bytes32 _inbox)
  {
    (_inbox,) = SolanaPda.findProgramAddress(
      abi.encodePacked(InboxAddress.SOLANA_INBOX_SEED, _routePda, _configurationRoot), _program
    );
  }

  /// @inheritdoc ISolanaCrypto
  /// @dev Printable ASCII, one `field: value` line per binding, so a Solana wallet renders it as text
  /// and the owner can read what they are authorizing instead of blind-signing a digest. Numbers are
  /// decimal; addresses, the configuration root and the calldata hash are lowercase `0x` hex.
  ///
  /// `data` is the keccak-256 hash of the inbox call's calldata rather than the calldata itself, so
  /// the message stays a bounded size regardless of what is being recovered.
  function inboxRecoveryMessage(
    uint256 _chainId,
    address _route,
    bytes32 _configurationRoot,
    address _target,
    uint256 _value,
    bytes32 _dataHash,
    uint256 _nonce
  ) public pure returns (string memory) {
    return string(
      abi.encodePacked(
        RECOVERY_MESSAGE_HEADER,
        "\nchain: ",
        _decimal(_chainId),
        "\nroute: ",
        _hex(uint256(uint160(_route)), 20),
        "\nconfig: ",
        _hex(uint256(_configurationRoot), 32),
        "\ntarget: ",
        _hex(uint256(uint160(_target)), 20),
        "\nvalue: ",
        _decimal(_value),
        "\ndata: ",
        _hex(uint256(_dataHash), 32),
        "\nnonce: ",
        _decimal(_nonce)
      )
    );
  }

  /// @inheritdoc ISolanaCrypto
  function verifyInboxRecovery(
    bytes32 _publicKey,
    bytes32 _configurationRoot,
    address _target,
    uint256 _value,
    bytes32 _dataHash,
    uint256 _nonce,
    bytes calldata _signature
  ) external view returns (bool) {
    // `block.chainid` and `msg.sender` are read here rather than passed in: the caller cannot ask
    // for a verdict on an authorization addressed to another chain or another route.
    string memory message =
      inboxRecoveryMessage(block.chainid, msg.sender, _configurationRoot, _target, _value, _dataHash, _nonce);

    return Ed25519.verify(_publicKey, bytes(message), _signature);
  }

  /// @dev Unsigned decimal, no separators. Hand-rolled because the OpenZeppelin string helpers reach
  /// for `mcopy`, which the Tron (Shanghai) profile cannot compile.
  function _decimal(uint256 _value) private pure returns (bytes memory _digits) {
    if (_value == 0) {
      return "0";
    }

    uint256 length;
    for (uint256 remaining = _value; remaining != 0; remaining /= 10) {
      ++length;
    }

    _digits = new bytes(length);
    for (uint256 i = length; i > 0;) {
      --i;
      _digits[i] = bytes1(uint8(48 + (_value % 10)));
      _value /= 10;
    }
  }

  /// @dev `0x`-prefixed lowercase hex of the low `_length` bytes of `_value`.
  function _hex(uint256 _value, uint256 _length) private pure returns (bytes memory _characters) {
    _characters = new bytes(2 + _length * 2);
    _characters[0] = "0";
    _characters[1] = "x";

    for (uint256 i = _length * 2; i > 0;) {
      --i;
      _characters[2 + i] = HEX_DIGITS[_value & 0xf];
      _value >>= 4;
    }
  }
}

