// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";

import {Access} from "./Access.sol";
import {Deposit} from "./Deposit.sol";
import {Destination} from "./Destination.sol";
import {InboxRecoveryBase} from "./InboxRecovery.sol";
import {RouteAccounting} from "./RouteAccounting.sol";
import {RouteAdapters} from "./RouteAdapters.sol";
import {ILocalAdapter} from "./interfaces/ILocalAdapter.sol";
import {IBridgeAdapter, BridgeExecution} from "./interfaces/IBridgeAdapter.sol";
import {RouteAsset} from "./interfaces/ISwapOracle.sol";
import {InboxConfig} from "./libraries/InboxConfig.sol";
import {RouteScopeStorage} from "./scope/RouteScopeStorage.sol";

/// @title TrailsPdas
/// @author Agustin Aguilar, Michael Standen
/// @notice Entry point for PDA inbox creation, route execution, and destination delivery.
/// @dev This is the canonical contract for Tron (Shanghai) and the Foundry test suite. It mixes in
/// RouteScopeStorage, the ordinary-storage inbox-callback scope backend, because the TVM does not
/// support EIP-1153 transient storage. The EVM deployment (`evm/TrailsPdasEvm.sol`) inherits
/// this contract and overrides only the scope primitives to use cheaper transient storage; all
/// route logic and types stay in this inheritance tree so the deployed behaviour and ABI are identical.
contract TrailsPdas is
  RouteAdapters,
  Deposit,
  Destination,
  RouteAccounting,
  Pausable,
  RouteScopeStorage,
  InboxRecoveryBase
{
  /// @notice Local operation to execute from the inbox before destination or bridge execution
  struct LocalOperation {
    ILocalAdapter adapter;
    uint256 tokenIn;
    uint256 tokenOut;
    uint256 amountIn;
    bytes adapterCalldata;
  }

  /// @notice Bridge operation to execute from the inbox after local operations
  struct BridgeOperation {
    IBridgeAdapter adapter;
    uint256 tokenIn;
    uint256 tokenOut;
    uint256 amountIn;
    uint256 minAmountOut;
    uint256 dstChainId;
    uint256[] feeTokens;
    bytes adapterCalldata;
  }

  event BridgeExecuted(
    bytes32 indexed _configurationRoot,
    address indexed _inbox,
    uint256 _dstChainId,
    bytes32 _landingInbox,
    address _tokenIn,
    address _tokenOut,
    address _adapter,
    bytes32 _operationId
  );
  event Bounced(
    bytes32 indexed _configurationRoot, address indexed _inbox, address _token, address _owner, uint256 _amount
  );
  event InboxTransactionSent(
    bytes32 indexed _configurationRoot, address indexed _inbox, address _owner, address _target, uint256 _value
  );

  error InvalidDestinationChain(uint256 _expected, uint256 _actual);
  error DestinationChainAlreadyReached(uint256 _chainId);
  error BridgeHopsExhausted(uint256 _currentChainId, uint256 _dstChainId);
  error InvalidBridgeDestinationChain(uint256 _currentChainId, uint256 _dstChainId);
  error InvalidFinalBridgeDestination(uint256 _expected, uint256 _actual);
  error UnauthorizedPdaOwner(address _sender, address _owner);
  error MissingRuntimeOwner(uint256 _chainId, Runtime _runtime);
  error InsufficientBridgeOutput(uint256 _minAmountOut, uint256 _amountOut);

  /// @param _initialAdmin Initial default admin
  /// @param _depositFeeCollector Initial non-zero recipient of deposit fees
  /// @param _initialLocalAdapters Initially registered local adapters
  /// @param _initialBridgeAdapters Initially registered bridge adapters
  constructor(
    address _initialAdmin,
    address _depositFeeCollector,
    ILocalAdapter[] memory _initialLocalAdapters,
    IBridgeAdapter[] memory _initialBridgeAdapters
  ) Access(_initialAdmin) Deposit(_depositFeeCollector) RouteAdapters(_initialLocalAdapters, _initialBridgeAdapters) {}

  /// @notice Pauses route execution
  function pause() external onlyPauser {
    _pause();
  }

  /// @notice Unpauses route execution
  function unpause() external onlyUnpauser {
    _unpause();
  }

  /// @notice Allows the PDA owner to execute an arbitrary transaction from their inbox
  function sendInboxTransaction(
    InboxConfig.Config calldata _config,
    address _target,
    uint256 _value,
    bytes calldata _data
  ) external returns (bytes memory _result) {
    address localOwner = _requireLocalOwner(_config);
    if (msg.sender != localOwner) {
      revert UnauthorizedPdaOwner(msg.sender, localOwner);
    }

    bytes32 configRoot = InboxConfig.rootCalldata(_config);
    address inbox = _requireInbox(configRoot);

    _result = _sendInboxTransaction(inbox, _target, _value, _data);
    emit InboxTransactionSent(configRoot, inbox, localOwner, _target, _value);
  }

  /// @notice Delivers the configured destination asset without running local operations, then refunds listed dust.
  function onlyDestination(InboxConfig.Config calldata _config, address[] calldata _dustTokens)
    external
    onlyExecutor
    whenNotPaused
    returns (bytes memory _result)
  {
    _requireDestinationChain(_config.destinationChainId);

    bytes32 configRoot = InboxConfig.rootCalldata(_config);
    address inbox = _requireInbox(configRoot);

    address localOwner = _requireLocalOwner(_config);
    (_result,) = _executeDestination(
      configRoot, inbox, _config.destinationTo, _config.destinationToken, _config.destinationCalldata, localOwner
    );
    _refundDust(inbox, localOwner, _dustTokens);
  }

  /// @notice Returns one current-chain inbox asset to the PDA owner
  function bounce(InboxConfig.Config calldata _config, address _token)
    external
    onlyExecutor
    whenNotPaused
    returns (bytes memory _result)
  {
    bytes32 configRoot = InboxConfig.rootCalldata(_config);
    address inbox = _requireInbox(configRoot);

    address localOwner = _requireLocalOwner(_config);
    uint256 amount;
    (_result, amount) = _transferDestinationAsset(inbox, localOwner, _token);
    emit Bounced(configRoot, inbox, _token, localOwner, amount);
  }

  /// @notice Pulls an ERC-20 from `_from` into the inbox, optionally using an ERC-2612 permit
  /// @dev Pulls the lesser of `_from`'s balance and the inbox's allowance after relaying any permit.
  /// The fee is paid in the same call. Prefer `localOperationsAndDestination` /
  /// `localOperationsAndBridge` when the pull should revert with the route.
  /// @param _config The inbox configuration
  /// @param _token ERC-20 to pull; native value is not supported
  /// @param _from Depositor to pull from
  /// @param _permit ERC-2612 permit to relay, or a zero `deadline` to rely on an existing allowance
  /// @param _feeAmount Fee deducted from the gross pull and bounded by the configured slippage
  /// @return _result Result bytes from the transfer into the inbox
  function pullDeposit(
    InboxConfig.Config calldata _config,
    address _token,
    address _from,
    ERC2612Permit calldata _permit,
    uint256 _feeAmount
  ) external onlyExecutor whenNotPaused returns (bytes memory _result) {
    address inbox = _requireInbox(InboxConfig.rootCalldata(_config));

    uint256 grossPulled;
    (_result, grossPulled) = _pullDeposit(inbox, _token, _from, _permit, _feeAmount);
    _requireDepositFeeWithinSlippage(_feeAmount, grossPulled, _config.maxSlippageBps);
  }

  /// @notice Executes local operations from the inbox and then delivers its configured destination asset
  /// @param _config The inbox configuration
  /// @param _assets Route asset table used by local operations and accounting
  /// @param _pull Optional ERC-20 pull from a permit or allowance; a zero `_pull.from` skips it
  /// @param _localOperations Local operations to execute before destination delivery
  /// @param _destinationAsset Index of the configured destination token in `_assets`
  /// @param _dustTokens Tokens whose remaining inbox balances should be returned to the PDA owner after delivery
  /// @return _result Result bytes from the last destination action
  function localOperationsAndDestination(
    InboxConfig.Config calldata _config,
    RouteAsset[] calldata _assets,
    Pull calldata _pull,
    LocalOperation[] calldata _localOperations,
    uint256 _destinationAsset,
    bytes calldata _oraclePayload,
    address[] calldata _dustTokens
  ) external onlyExecutor whenNotPaused returns (bytes memory _result) {
    _requireDestinationChain(_config.destinationChainId);

    bytes32 configRoot = InboxConfig.rootCalldata(_config);
    address inbox = _requireInbox(configRoot);
    _executePull(inbox, _config.maxSlippageBps, _pull);
    _requireLocalAsset(_assets, _destinationAsset);
    address destinationToken = InboxConfig.bytes32ToAddress(_config.destinationToken);
    if (_assets[_destinationAsset].token != destinationToken) {
      revert InvalidAssetToken(_destinationAsset, _config.destinationToken, _assets[_destinationAsset].token);
    }

    // Always observe native value: if the route doesn't declare it as an asset (so the normal
    // accounting would value its deltas), freeze it — undeclared native ETH must not leave the inbox
    // during the adapter phase. Native balance is always readable, so this needs no asset entry.
    bool ethTracked = _nativeEthTracked(_assets);
    uint256 ethBefore = ethTracked ? 0 : inbox.balance;

    // Snapshot around local operations so fairness is based on route deltas,
    // not whatever the inbox happened to hold before execution.
    uint256[] memory startingBalances = _snapshotBalances(inbox, _assets);

    // Scope the inbox callbacks to this route + inbox and gate ERC-20 outflow to declared assets.
    _beginRouteContext(inbox, _assets);
    _executeLocalOperations(inbox, _assets, _localOperations);
    _endRouteContext();

    if (!ethTracked && inbox.balance < ethBefore) {
      revert UndeclaredNativeEthSpent(inbox, ethBefore, inbox.balance);
    }

    uint256[] memory endingBalances = _snapshotBalances(inbox, _assets);
    _validateDestinationRoute(
      _assets, startingBalances, endingBalances, _destinationAsset, _oraclePayload, _config.maxSlippageBps
    );

    address localOwner = _requireLocalOwner(_config);
    (_result,) = _executeDestination(
      configRoot, inbox, _config.destinationTo, _config.destinationToken, _config.destinationCalldata, localOwner
    );
    _refundDust(inbox, localOwner, _dustTokens);
  }

  /// @notice Executes local operations from the inbox and then starts a bridge
  /// @param _config The inbox configuration
  /// @param _assets Route asset table used by local operations, bridge, fees, and accounting
  /// @param _pull Optional ERC-20 pull from a permit or allowance; a zero `_pull.from` skips it
  /// @param _localOperations Local operations to execute before bridging
  /// @param _bridge Bridge operation to execute
  /// @param _dustTokens Tokens whose remaining inbox balances should be returned to the PDA owner after bridging
  /// @return _operationId Operation ID returned by the bridge adapter
  function localOperationsAndBridge(
    InboxConfig.Config calldata _config,
    RouteAsset[] calldata _assets,
    Pull calldata _pull,
    LocalOperation[] calldata _localOperations,
    BridgeOperation calldata _bridge,
    bytes calldata _oraclePayload,
    address[] calldata _dustTokens
  ) external onlyExecutor whenNotPaused returns (bytes32 _operationId) {
    _validateBridgeAvailability(_config.destinationChainId, _bridge.dstChainId, _config.bridgeHopsRemaining);

    // A bridge moves the inbox onto another runtime. Both the immediate landing chain and the
    // terminal destination chain must have an owner expressed in their runtime's key system, or the
    // inbox would be uncontrollable/unrecoverable there (the trust gap that otherwise forces an
    // executor escape hatch). Disallow the bridge unless those owners are defined. Keep the resolved
    // runtimes so the config-domain checks below do not repeat the registry lookups.
    Runtime bridgeRuntime = _requireRuntimeOwner(_config.owners, _bridge.dstChainId);
    bool bridgeLandsOnDestination = _bridge.dstChainId == _config.destinationChainId;
    Runtime destinationRuntime =
      bridgeLandsOnDestination ? bridgeRuntime : _requireRuntimeOwner(_config.owners, _config.destinationChainId);

    bytes32 configRoot = InboxConfig.rootCalldata(_config);
    address inbox = _requireInbox(configRoot);
    _executePull(inbox, _config.maxSlippageBps, _pull);

    // The inbox lands on the same config with one less hop; that is the root the remote route derives.
    uint256 landingHops = _config.bridgeHopsRemaining - 1;

    if (bridgeRuntime == Runtime.SVM) {
      InboxConfig.requireSolanaDomain(_config, landingHops, _bridge.dstChainId, uint8(bridgeRuntime));
    }
    if (!bridgeLandsOnDestination && destinationRuntime == Runtime.SVM) {
      InboxConfig.requireSolanaDomain(_config, landingHops, _config.destinationChainId, uint8(destinationRuntime));
    }

    bytes32 landingInbox = _remoteInboxRecipient(_bridge.dstChainId, InboxConfig.rootCalldata(_config, landingHops));
    _requireLocalAsset(_assets, _bridge.tokenIn);
    _requireAsset(_assets, _bridge.tokenOut, _bridge.dstChainId);

    // Freeze undeclared native value across the whole adapter phase (local ops + bridge), same as
    // the destination path. The bridge adapter also re-enters via the inbox callback, so the check
    // must span it.
    bool ethTracked = _nativeEthTracked(_assets);
    uint256 ethBefore = ethTracked ? 0 : inbox.balance;

    // Bridge amounts and fees can depend on local operation output. Snapshot
    // after local operations, execute the bridge, then validate with the quote
    // returned by the adapter and a second snapshot of what the bridge call
    // took. A validation revert rolls back the bridge call.
    _beginRouteContext(inbox, _assets);

    uint256[] memory startingBalances = _snapshotBalances(inbox, _assets);

    _executeLocalOperations(inbox, _assets, _localOperations);

    uint256[] memory endingBalances = _snapshotBalances(inbox, _assets);

    BridgeExecution memory bridgeExecution = _executeBridgeAdapter(
      _bridge.adapter,
      inbox,
      _assets[_bridge.tokenIn].token,
      _assets[_bridge.tokenOut].token,
      _bridge.amountIn,
      _bridge.minAmountOut,
      _bridge.dstChainId,
      landingInbox,
      _bridge.adapterCalldata
    );

    _endRouteContext();

    if (!ethTracked && inbox.balance < ethBefore) {
      revert UndeclaredNativeEthSpent(inbox, ethBefore, inbox.balance);
    }

    _validateBridgeRoute(
      _assets,
      inbox,
      startingBalances,
      endingBalances,
      _bridge.tokenIn,
      _bridge.tokenOut,
      _bridge.feeTokens,
      bridgeExecution.quote,
      _oraclePayload,
      _config.maxSlippageBps
    );

    if (bridgeExecution.quote.amountOut < _bridge.minAmountOut) {
      revert InsufficientBridgeOutput(_bridge.minAmountOut, bridgeExecution.quote.amountOut);
    }

    // The local owner only receives dust here, so a route with nothing to refund does not need one.
    if (_dustTokens.length != 0) {
      _refundDust(inbox, _requireLocalOwner(_config), _dustTokens);
    }

    emit BridgeExecuted(
      configRoot,
      inbox,
      _bridge.dstChainId,
      landingInbox,
      _assets[_bridge.tokenIn].token,
      _assets[_bridge.tokenOut].token,
      address(_bridge.adapter),
      bridgeExecution.operationId
    );

    return bridgeExecution.operationId;
  }

  /// @notice Resolves the inbox's local secp256k1 owner, reverting if it is undefined.
  /// @dev EVM and Tron both use 20-byte secp256k1 addresses, but the config keeps separate owners
  /// because the same inbox can land on either runtime.
  function _requireLocalOwner(InboxConfig.Config calldata _config) private view returns (address _owner) {
    Runtime runtime = _localRuntime();
    if (runtime == Runtime.TVM) {
      _owner = _config.owners.tron;
    } else {
      _owner = _config.owners.evm;
    }

    if (_owner == address(0)) {
      revert MissingRuntimeOwner(block.chainid, runtime);
    }
  }

  function _revertMissingRuntimeOwner(uint256 _chainId, Runtime _runtime) internal pure override {
    revert MissingRuntimeOwner(_chainId, _runtime);
  }

  /// @notice Requires the config to carry an owner for the runtime that `_chainId` lands on.
  function _requireRuntimeOwner(InboxConfig.Owners calldata _owners, uint256 _chainId)
    private
    view
    returns (Runtime runtime)
  {
    runtime = _remoteRuntime(_chainId);
    bool defined;
    if (runtime == Runtime.SVM) {
      defined = _owners.solana != bytes32(0);
    } else if (runtime == Runtime.TVM) {
      defined = _owners.tron != address(0);
    } else {
      defined = _owners.evm != address(0);
    }

    if (!defined) {
      revert MissingRuntimeOwner(_chainId, runtime);
    }
  }

  function _requireDestinationChain(uint256 _destinationChainId) private view {
    if (_destinationChainId != block.chainid) {
      revert InvalidDestinationChain(_destinationChainId, block.chainid);
    }
  }

  function _validateBridgeAvailability(uint256 _finalChainId, uint256 _dstChainId, uint256 _bridgeHopsRemaining)
    private
    view
  {
    // Every bridge consumes route budget and lands on the same config with one
    // less hop. The terminal chain can only execute destination delivery.
    uint256 currentChainId = block.chainid;
    if (currentChainId == _finalChainId) {
      revert DestinationChainAlreadyReached(currentChainId);
    }

    if (_bridgeHopsRemaining == 0) {
      revert BridgeHopsExhausted(currentChainId, _dstChainId);
    }

    if (_dstChainId == currentChainId) {
      revert InvalidBridgeDestinationChain(currentChainId, _dstChainId);
    }

    if (_bridgeHopsRemaining == 1 && _dstChainId != _finalChainId) {
      revert InvalidFinalBridgeDestination(_finalChainId, _dstChainId);
    }
  }

  function _executePull(address _inbox, uint256 _maxSlippageBps, Pull calldata _pull) private {
    if (_pull.from == address(0)) {
      return;
    }

    (, uint256 grossPulled) = _pullDeposit(_inbox, _pull.token, _pull.from, _pull.permit, _pull.feeAmount);
    _requireDepositFeeWithinSlippage(_pull.feeAmount, grossPulled, _maxSlippageBps);
  }

  function _executeLocalOperations(
    address _inbox,
    RouteAsset[] calldata _assets,
    LocalOperation[] calldata _localOperations
  ) private {
    // Local operations reference the shared asset table by index. Adapters still
    // receive plain token addresses and operate entirely through the inbox.
    uint256 numLocalOperations = _localOperations.length;
    for (uint256 i = 0; i < numLocalOperations; i++) {
      _requireLocalAsset(_assets, _localOperations[i].tokenIn);
      _requireLocalAsset(_assets, _localOperations[i].tokenOut);
      _executeLocalAdapter(
        _localOperations[i].adapter,
        _inbox,
        _assets[_localOperations[i].tokenIn].token,
        _assets[_localOperations[i].tokenOut].token,
        _localOperations[i].amountIn,
        _localOperations[i].adapterCalldata
      );
    }
  }

  /// @notice Fingerprint of this deployment's effective router configuration.
  /// @dev Computed by the governor satellite, which owns the role registry and reads the rest of the
  /// configuration back through this contract's getters. Forwarded here so tooling keeps querying one
  /// address; see `TrailsPdasGovernor.configurationHash` for what is covered.
  function configurationHash() external view returns (bytes32) {
    return _governor().configurationHash();
  }
}

src/TrailsPdasGovernor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {
  AccessControlDefaultAdminRules
} from "@openzeppelin/contracts/access/extensions/AccessControlDefaultAdminRules.sol";

import {ITrailsPdasGoverned} from "./interfaces/ITrailsPdasGoverned.sol";
import {EnumerableSet} from "./libraries/EnumerableSet.sol";

/// @title TrailsPdasGovernor
/// @author Agustin Aguilar
/// @notice Governance satellite of a `TrailsPdas` route: OpenZeppelin two-step default admin, role
/// grant/revoke, role-member enumeration, and the deployment's `configurationHash`.
/// @dev The route deploys this from its own constructor (same reasoning as `SolanaCrypto`: the code
/// is committed by the route's creation code, and the route's creation code stays identical across
/// chains so CREATE2 same-address determinism holds). Every role change is mirrored into the route's
/// flat role storage through `ITrailsPdasGoverned`, so the route's hot-path authorization checks stay
/// plain storage reads. This contract holds no funds and has no authority over inboxes.
contract TrailsPdasGovernor is AccessControlDefaultAdminRules {
  using EnumerableSet for EnumerableSet.AddressSet;
  using EnumerableSet for EnumerableSet.Bytes32Set;

  bytes32 public constant EXECUTOR_ROLE = keccak256("EXECUTOR_ROLE");
  bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
  bytes32 public constant UNPAUSER_ROLE = keccak256("UNPAUSER_ROLE");

  bytes32 private constant CONFIGURATION_HASH_DOMAIN = keccak256("TrailsPdas.EvmConfiguration.v1");
  bytes32 private constant ROLE_MEMBER_CONFIGURATION_ENTRY = keccak256("TrailsPdas.EvmConfiguration.roleMember.v1");
  bytes32 private constant LOCAL_ADAPTER_CONFIGURATION_ENTRY = keccak256("TrailsPdas.EvmConfiguration.localAdapter.v1");
  bytes32 private constant BRIDGE_ADAPTER_CONFIGURATION_ENTRY =
    keccak256("TrailsPdas.EvmConfiguration.bridgeAdapter.v1");
  bytes32 private constant REMOTE_INBOX_CONFIGURATION_ENTRY = keccak256("TrailsPdas.EvmConfiguration.remoteInbox.v1");

  /// @notice The route this governor administers.
  /// @dev Storage rather than `immutable` on purpose: the OpenZeppelin base constructor grants the
  /// initial admin before this constructor body runs, and `_sync` must be able to observe that the
  /// route is not wired yet (the route seeds its own initial admin).
  ITrailsPdasGoverned public route;

  mapping(bytes32 role => EnumerableSet.AddressSet) private _roleMembers;
  EnumerableSet.Bytes32Set private _configuredRoles;

  /// @param _initialAdmin Initial default admin, identical to the one the route seeds for itself
  /// @param _route The route being administered
  constructor(address _initialAdmin, ITrailsPdasGoverned _route) AccessControlDefaultAdminRules(0, _initialAdmin) {
    route = _route;
  }

  function _grantRole(bytes32 _role, address _account) internal virtual override returns (bool granted) {
    granted = super._grantRole(_role, _account);
    if (granted) {
      _roleMembers[_role].add(_account);
      _configuredRoles.add(_role);
      _sync(_role, _account, true);
    }
  }

  function _revokeRole(bytes32 _role, address _account) internal virtual override returns (bool revoked) {
    revoked = super._revokeRole(_role, _account);
    if (revoked) {
      _roleMembers[_role].remove(_account);
      if (_roleMembers[_role].length() == 0) {
        _configuredRoles.remove(_role);
      }
      _sync(_role, _account, false);
    }
  }

  /// @dev Mirrors a role change into the route. `DEFAULT_ADMIN_ROLE` is single-holder under
  /// `AccessControlDefaultAdminRules`, so it maps onto the route's admin slot rather than its role
  /// mapping (an accepted transfer revokes the old admin, then grants the new one).
  function _sync(bytes32 _role, address _account, bool _granted) private {
    if (address(route) == address(0)) {
      return; // Constructor-time seed: the route seeds the same initial admin itself.
    }
    if (_role == DEFAULT_ADMIN_ROLE) {
      route.setDefaultAdmin(_granted ? _account : address(0));
    } else {
      route.setRole(_role, _account, _granted);
    }
  }

  /// @notice Returns every current member of `_role`.
  /// @dev Ordering is an implementation detail; `configurationHash()` is order independent.
  function getRoleMembers(bytes32 _role) external view returns (address[] memory) {
    return _roleMembers[_role].values();
  }

  /// @notice Fingerprint of the route's effective configuration.
  /// @dev Registry entries are folded with a domain-separated XOR and an entry count, making the
  /// result independent of insertion order and stable after add/remove round trips. Covers the
  /// governor-owned role registry plus the route-owned configuration read through its getters; not
  /// mutable configuration inside adapter or oracle contracts.
  function configurationHash() external view returns (bytes32) {
    (address pendingAdmin, uint48 pendingAdminSchedule) = pendingDefaultAdmin();
    (uint48 pendingDelay, uint48 pendingDelaySchedule) = pendingDefaultAdminDelay();

    (bytes32 registryAccumulator, uint256 registryEntries, uint8 fallbackRuntime, bytes32 fallbackParamsHash) =
      _configurationRegistry();

    return keccak256(
      abi.encode(
        CONFIGURATION_HASH_DOMAIN,
        defaultAdmin(),
        pendingAdmin,
        pendingAdminSchedule,
        defaultAdminDelay(),
        pendingDelay,
        pendingDelaySchedule,
        route.paused(),
        route.swapOracle(),
        route.depositFeeCollector(),
        fallbackRuntime,
        fallbackParamsHash,
        registryEntries,
        registryAccumulator
      )
    );
  }

  /// @dev Folds the access, adapter and remote inbox registries into one accumulator and entry count.
  /// Split out of `configurationHash()` to keep its frame shallow enough for `forge coverage`.
  function _configurationRegistry()
    private
    view
    returns (bytes32 _accumulator, uint256 _entryCount, uint8 _fallbackRuntime, bytes32 _fallbackParamsHash)
  {
    (bytes32 accessAccumulator, uint256 accessEntries) = _accessConfigurationRegistry();
    (bytes32 adapterAccumulator, uint256 adapterEntries) = _adapterConfigurationRegistry();
    bytes32 inboxAccumulator;
    uint256 inboxEntries;
    (inboxAccumulator, inboxEntries, _fallbackRuntime, _fallbackParamsHash) = _inboxConfigurationRegistry();
    _accumulator = accessAccumulator ^ adapterAccumulator ^ inboxAccumulator;
    _entryCount = accessEntries + adapterEntries + inboxEntries;
  }

  function _accessConfigurationRegistry() private view returns (bytes32 _accumulator, uint256 _entryCount) {
    bytes32[] memory roles = _configuredRoles.values();
    for (uint256 i = 0; i < roles.length; i++) {
      address[] memory members = _roleMembers[roles[i]].values();
      for (uint256 j = 0; j < members.length; j++) {
        _accumulator ^= keccak256(abi.encode(ROLE_MEMBER_CONFIGURATION_ENTRY, roles[i], members[j]));
        _entryCount++;
      }
    }
  }

  function _adapterConfigurationRegistry() private view returns (bytes32 _accumulator, uint256 _entryCount) {
    address[] memory local = route.localAdapters();
    for (uint256 i = 0; i < local.length; i++) {
      _accumulator ^= keccak256(abi.encode(LOCAL_ADAPTER_CONFIGURATION_ENTRY, local[i]));
    }

    address[] memory bridge = route.bridgeAdapters();
    for (uint256 i = 0; i < bridge.length; i++) {
      _accumulator ^= keccak256(abi.encode(BRIDGE_ADAPTER_CONFIGURATION_ENTRY, bridge[i]));
    }

    _entryCount = local.length + bridge.length;
  }

  function _inboxConfigurationRegistry()
    private
    view
    returns (bytes32 _accumulator, uint256 _entryCount, uint8 _fallbackRuntime, bytes32 _fallbackParamsHash)
  {
    bytes32[] memory chainIds = route.remoteInboxChains();
    for (uint256 i = 0; i < chainIds.length; i++) {
      uint256 chainId = uint256(chainIds[i]);
      ITrailsPdasGoverned.RemoteInbox memory remote = route.remoteInbox(chainId);
      _accumulator ^= keccak256(
        abi.encode(REMOTE_INBOX_CONFIGURATION_ENTRY, chainId, remote.runtime, keccak256(remote.params))
      );
    }
    _entryCount = chainIds.length;

    ITrailsPdasGoverned.RemoteInbox memory fallbackRemote = route.remoteInboxFallback();
    _fallbackRuntime = fallbackRemote.runtime;
    _fallbackParamsHash = keccak256(fallbackRemote.params);
  }
}

