// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

/// @title ISolanaCrypto
/// @notice The Solana-native primitives the route cannot express in its own bytecode budget.
/// @dev Implemented by `SolanaCrypto`, which every route deploys from its own constructor. The
/// interface exists so the route holds one narrow, typed handle instead of the whole implementation.
interface ISolanaCrypto {
  /// @notice Derives the Solana inbox PDA for a configuration root.
  /// @param _program The Trails program id on Solana.
  /// @param _routePda The program's route PDA.
  /// @param _configurationRoot The inbox configuration root.
  /// @return The canonical (highest off-curve bump) inbox address.
  function inboxProgramAddress(bytes32 _program, bytes32 _routePda, bytes32 _configurationRoot)
    external
    view
    returns (bytes32);

  /// @notice The exact message a Solana owner signs to authorize one inbox recovery.
  /// @dev Pure and fully parameterized so clients and tests can reproduce the bytes for any chain
  /// and route, not only the caller's own.
  function inboxRecoveryMessage(
    uint256 _chainId,
    address _route,
    bytes32 _configurationRoot,
    address _target,
    uint256 _value,
    bytes32 _dataHash,
    uint256 _nonce
  ) external pure returns (string memory);

  /// @notice Verifies a Solana owner's ed25519 signature over an inbox recovery.
  /// @dev The message is rebuilt from `block.chainid` and `msg.sender`, so a caller can only ever
  /// verify an authorization scoped to itself on this chain.
  /// @param _publicKey The configured Solana owner (a 32-byte ed25519 public key).
  /// @param _signature The 64-byte `R || S` ed25519 signature.
  function verifyInboxRecovery(
    bytes32 _publicKey,
    bytes32 _configurationRoot,
    address _target,
    uint256 _value,
    bytes32 _dataHash,
    uint256 _nonce,
    bytes calldata _signature
  ) external view returns (bool);
}

