// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

/// @title ITrailsPdasGoverned
/// @notice The router surface the `TrailsPdasGovernor` satellite writes to (role mirroring) and reads
/// (`configurationHash`).
interface ITrailsPdasGoverned {
  /// @dev ABI mirror of `Inboxes.RemoteInbox`; `runtime` carries the `Inboxes.Runtime` enum.
  struct RemoteInbox {
    uint8 runtime;
    bytes params;
  }

  /// @notice Mirrors a non-admin role grant or revoke into router storage. Governor only.
  function setRole(bytes32 _role, address _account, bool _granted) external;

  /// @notice Mirrors the current default admin into router storage. Governor only.
  function setDefaultAdmin(address _admin) external;

  function paused() external view returns (bool);
  function swapOracle() external view returns (address);
  function depositFeeCollector() external view returns (address);
  function localAdapters() external view returns (address[] memory);
  function bridgeAdapters() external view returns (address[] memory);
  function remoteInboxChains() external view returns (bytes32[] memory);
  function remoteInbox(uint256 _chainId) external view returns (RemoteInbox memory);
  function remoteInboxFallback() external view returns (RemoteInbox memory);
}

src/libraries/Ed25519.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {Sha512} from "./Sha512.sol";

/// @title Ed25519
/// @notice RFC 8032 ed25519 signature verification, in software.
/// @dev Solana owners hold ed25519 keys, and no EVM (or TVM) chain exposes an ed25519 precompile, so
///      a Solana owner can only authorize anything here if the curve arithmetic runs on-chain. This
///      is the one primitive that stands between a Solana-owned inbox funded on EVM/Tron and a
///      permanent loss of the deposit.
///
///      ## What is accepted
///
///      Verification is the strict, cofactor-less equation `[S]B = R + [h]A`, with
///      `h = SHA512(R || A || M) mod L`, plus these refusals:
///
///      - a signature that is not exactly 64 bytes,
///      - `S >= L` (the non-canonical scalar encoding that makes signatures malleable),
///      - a public key whose `y` coordinate is `>= p`, or that is not on the curve,
///      - a public key of small order (`[8]A` is the identity), which would otherwise let anyone
///        forge for that key,
///      - a signature `R` that is not a canonical point encoding, or that is a small-order point
///        (`[8]R` is the identity). A small-order `R` cannot satisfy the equation for a
///        prime-subgroup key unless the signer holds the private scalar, so this is not a forgery
///        vector — but `verify_strict` refuses it, and this contract means to match.
///
///      For canonically encoded keys and signatures that is exactly the acceptance set of
///      `ed25519-dalek`'s `verify_strict` — what a Solana validator applies. The contract is
///      stricter in one corner only: `verify_strict` reduces a non-canonical `y >= p` modulo `p`,
///      so it accepts such an `R` or `A` when the signer crafted the signature for it, while this
///      contract refuses non-canonical encodings outright. Acceptance here therefore always implies
///      acceptance by a validator; the reverse holds for every input a real signer can produce
///      without deliberately choosing a second encoding of a point.
///      `spec/vectors/ed25519-verify-strict.json` pins all of this against `ed25519-dalek` itself,
///      including the torsion corner cases.
///
///      ## Representation
///
///      Points are extended twisted Edwards coordinates `(X : Y : Z : T)` with `x = X/Z`, `y = Y/Z`
///      and `T/Z = xy`, using the `a = -1` doubling and the unified `k = 2d` addition. Both are
///      complete for ed25519 (`d` is a non-square), so no branch on exceptional inputs is needed.
///      The two scalar multiplications are interleaved (Straus), which halves the doublings.
library Ed25519 {
  /// @dev Field prime p = 2^255 - 19.
  uint256 internal constant P = 0x7fffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffed;
  /// @dev Group order L = 2^252 + 27742317777372353535851937790883648493.
  uint256 internal constant L = 0x1000000000000000000000000000000014def9dea2f79cd65812631a5cf5d3ed;
  /// @dev Edwards curve constant d = -121665/121666 mod p.
  uint256 private constant D = 0x52036cee2b6ffe738cc740797779e89800700a4d4141d8ab75eb4dca135978a3;
  /// @dev 2d mod p, the addition formula's k.
  uint256 private constant D2 = 0x2406d9dc56dffce7198e80f2eef3d13000e0149a8283b156ebd69b9426b2f159;
  /// @dev sqrt(-1) mod p = 2^((p-1)/4).
  uint256 private constant SQRT_M1 = 0x2b8324804fc1df0b2b4d00993dfbd7a72f431806ad2fe478c4ee1b274a0ea0b0;
  /// @dev Square-root exponent (p+3)/8.
  uint256 private constant P_PLUS_3_DIV_8 = 0x0ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffe;
  /// @dev Inversion exponent p-2.
  uint256 private constant P_MINUS_2 = 0x7fffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffeb;
  /// @dev 2^256 mod L, used to fold a 512-bit hash into a scalar.
  uint256 private constant TWO_256_MOD_L = 0x0ffffffffffffffffffffffffffffffec6ef5bf4737dcf70d6ec31748d98951d;
  /// @dev Base point B.
  uint256 private constant BX = 0x216936d3cd6e53fec0a4e231fdd6dc5c692cc7609525a7b2c9562d608f25d51a;
  uint256 private constant BY = 0x6666666666666666666666666666666666666666666666666666666666666658;
  /// @dev Low 255 bits; clears the compressed encoding's x-coordinate sign bit.
  uint256 private constant MASK_255 = 0x7fffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff;

  /// @notice A curve point in extended coordinates.
  struct Point {
    uint256 x;
    uint256 y;
    uint256 z;
    uint256 t;
  }

  /// @notice Verifies an ed25519 signature.
  /// @param publicKey The 32-byte compressed public key (a Solana pubkey, verbatim).
  /// @param message The signed message bytes.
  /// @param signature The 64-byte `R || S` signature.
  /// @return True when the signature is valid for `publicKey` over `message`.
  function verify(bytes32 publicKey, bytes memory message, bytes memory signature) internal view returns (bool) {
    if (signature.length != 64) {
      return false;
    }

    bytes32 r;
    uint256 s;
    assembly ("memory-safe") {
      r := mload(add(signature, 0x20))
      s := mload(add(signature, 0x40))
    }
    s = fromLittleEndian(s);
    // A canonical scalar is reduced. Accepting `S + L` would make every signature malleable.
    if (s >= L) {
      return false;
    }

    (bool onCurve, Point memory a) = decompress(publicKey);
    if (!onCurve) {
      return false;
    }
    // Small-order keys (including the identity) satisfy the verification equation for signatures
    // anybody can produce, so no such key may ever stand in for an owner.
    if (_isSmallOrder(a)) {
      return false;
    }

    // `verify_strict` also refuses a small-order `R`. The equation check below would catch a
    // non-canonical encoding on its own, but it would accept e.g. `R = identity` when the signer
    // knows the private scalar, and a validator would not — decompress and rule it out.
    (bool rOnCurve, Point memory rPoint) = decompress(r);
    if (!rOnCurve) {
      return false;
    }
    if (_isSmallOrder(rPoint)) {
      return false;
    }

    (bytes32 hashHi, bytes32 hashLo) = Sha512.hash(abi.encodePacked(r, publicKey, message));
    uint256 h = reduceScalar(hashHi, hashLo);

    // [S]B - [h]A, then compare against R in its canonical encoding.
    Point memory negA = Point({x: _neg(a.x), y: a.y, z: a.z, t: _neg(a.t)});
    return compress(_doubleScalarMul(s, negA, h)) == r;
  }

  /// @notice Decodes a compressed point.
  /// @dev Recovers `x` from `x^2 = (y^2 - 1) / (d*y^2 + 1)` and the encoded sign bit. Rejects a
  ///      non-canonical `y` (`y >= p`), a `y` with no corresponding `x`, and the `x == 0` encoding
  ///      that sets the sign bit.
  /// @return ok False when `encoded` is not a canonical point encoding.
  /// @return point The decoded point.
  function decompress(bytes32 encoded) internal view returns (bool ok, Point memory point) {
    uint256 raw = fromLittleEndian(uint256(encoded));
    uint256 sign = raw >> 255;
    uint256 y = raw & MASK_255;
    if (y >= P) {
      return (false, point);
    }

    uint256 yy = mulmod(y, y, P);
    uint256 u = addmod(yy, P - 1, P); // y^2 - 1
    uint256 v = addmod(mulmod(D, yy, P), 1, P); // d*y^2 + 1
    if (v == 0) {
      return (false, point);
    }

    uint256 xx = mulmod(u, _modexp(v, P_MINUS_2), P);
    uint256 x = _modexp(xx, P_PLUS_3_DIV_8);
    if (mulmod(x, x, P) != xx) {
      x = mulmod(x, SQRT_M1, P);
      if (mulmod(x, x, P) != xx) {
        return (false, point); // y is not the ordinate of any curve point
      }
    }

    if (x == 0 && sign == 1) {
      return (false, point); // the only non-canonical sign bit
    }
    if ((x & 1) != sign) {
      x = P - x;
    }

    return (true, Point({x: x, y: y, z: 1, t: mulmod(x, y, P)}));
  }

  /// @notice Encodes a point as its canonical 32 bytes: little-endian `y` with `x`'s low bit on top.
  function compress(Point memory point) internal view returns (bytes32) {
    uint256 zInv = _modexp(point.z, P_MINUS_2);
    uint256 x = mulmod(point.x, zInv, P);
    uint256 y = mulmod(point.y, zInv, P);

    return bytes32(fromLittleEndian(y | ((x & 1) << 255)));
  }

  /// @notice Folds a 512-bit SHA-512 digest, read little-endian, into a scalar mod L.
  /// @param hi The digest's first 32 bytes, which hold the low limb.
  /// @param lo The digest's last 32 bytes, which hold the high limb.
  function reduceScalar(bytes32 hi, bytes32 lo) internal pure returns (uint256) {
    uint256 low = fromLittleEndian(uint256(hi)) % L;
    uint256 high = fromLittleEndian(uint256(lo)) % L;

    return addmod(low, mulmod(high, TWO_256_MOD_L, L), L);
  }

  /// @notice `[scalar]B`.
  /// @dev Not used by verification (which interleaves both multiplications), so it is dropped from
  ///      the deployed code unless a caller — the test signer — references it.
  function scalarMultBase(uint256 scalar) internal pure returns (Point memory result) {
    Point memory base = _base();
    result = _identity();

    // 256 bits, not the 253 a reduced scalar needs: a clamped ed25519 secret scalar has bit 254 set.
    for (uint256 i = 256; i > 0;) {
      unchecked {
        --i;
      }
      result = _double(result);
      if ((scalar >> i) & 1 == 1) {
        result = _add(result, base);
      }
    }
  }

  /// @dev `[s]B + [h]other`, interleaved so the two multiplications share one doubling chain.
  ///      `other` must be affine (`z == 1`), which every decompressed point is. The loop runs on the
  ///      stack in Yul, with the three addends (`B`, `other`, `B + other`) precomputed in the cached
  ///      form `(Y+X, Y-X, 2d*T, 2Z)` that add-2008-hwcd-3 consumes.
  ///
  ///      Reduction bounds: every `mulmod`/`addmod` result is `< p`, so `sub(P, v)` of one is in
  ///      `(0, p]`, and a plain `add` of two such terms is `< 2p = 2^256 - 38`. It cannot wrap, and
  ///      `mulmod` is exact for any 256-bit operands, so a sum is left unreduced only when its sole
  ///      consumer is a `mulmod`. Sums that feed another `add` or a `sub(P, _)` go through `addmod`.
  ///      Internal rather than private only so the differential test can compare it point by point.
  function _doubleScalarMul(uint256 s, Point memory other, uint256 h) internal pure returns (Point memory result) {
    uint256 rx;
    uint256 ry;
    uint256 rz;
    uint256 rt;
    assembly ("memory-safe") {
      // Scratch table past the free memory pointer, never claimed: nothing allocates inside this
      // block, and the `Point` allocated after it may overwrite it. Entry k (1 = B, 2 = other,
      // 3 = B + other) sits at tbl + (k - 1) * 0x80; the two scalars follow at 0x180 and 0x1a0.
      let tbl := mload(0x40)

      // B, affine: (BY + BX, BY - BX, 2d * BX * BY, 2).
      mstore(tbl, addmod(BY, BX, P))
      mstore(add(tbl, 0x20), addmod(BY, sub(P, BX), P))
      mstore(add(tbl, 0x40), mulmod(mulmod(BX, BY, P), D2, P))
      mstore(add(tbl, 0x60), 2)

      // other, affine. Its coordinates come from `decompress` and `_neg`, so they are all `< p`.
      let ox := mload(other)
      let oy := mload(add(other, 0x20))
      let ot := mload(add(other, 0x60))
      mstore(add(tbl, 0x80), addmod(oy, ox, P))
      mstore(add(tbl, 0xa0), addmod(oy, sub(P, ox), P))
      mstore(add(tbl, 0xc0), mulmod(ot, D2, P))
      mstore(add(tbl, 0xe0), 2)

      // B + other: add-2008-hwcd-3 of `other` (Z1 = 1) with cached B (2*Z2 = 2), so D = 2.
      {
        let a := mulmod(add(oy, sub(P, ox)), mload(add(tbl, 0x20)), P) // (Y1-X1)*(Y2-X2), operand < 2p
        let b := mulmod(add(oy, ox), mload(tbl), P) // (Y1+X1)*(Y2+X2), operand < 2p
        let c := mulmod(ot, mload(add(tbl, 0x40)), P) // T1*2d*T2
        let e := add(b, sub(P, a)) // < 2p
        let f := add(2, sub(P, c)) // <= p + 2
        let g := add(2, c) // < p + 2
        let hh := add(b, a) // < 2p
        let x3 := mulmod(e, f, P)
        let y3 := mulmod(g, hh, P)
        let z3 := mulmod(f, g, P)
        let t3 := mulmod(e, hh, P)
        mstore(add(tbl, 0x100), addmod(y3, x3, P))
        mstore(add(tbl, 0x120), addmod(y3, sub(P, x3), P))
        mstore(add(tbl, 0x140), mulmod(t3, D2, P))
        mstore(add(tbl, 0x160), addmod(z3, z3, P))
      }

      // The scalars live in memory rather than on the stack; fewer live slots keep via-IR from
      // spilling the point coordinates.
      mstore(add(tbl, 0x180), s)
      mstore(add(tbl, 0x1a0), h)

      // Start from the identity (0 : 1 : 1 : 0).
      rx := 0
      ry := 1
      rz := 1
      rt := 0
      // Both scalars are reduced mod L < 2^253, so 253 bits cover them.
      for { let i := 253 } i {} {
        i := sub(i, 1)

        // Doubling for a = -1 (dbl-2008-hwcd). rx, ry, rz are `< p` on entry (mulmod outputs or
        // the identity's 0/1), and T is not read.
        {
          let a := mulmod(rx, rx, P)
          let b := mulmod(ry, ry, P)
          let xy := add(rx, ry) // < 2p
          let ab := addmod(a, b, P) // reduced: it feeds sub(P, _) twice
          let e := add(mulmod(xy, xy, P), sub(P, ab)) // E = (X+Y)^2 - A - B, < 2p
          let g := addmod(b, sub(P, a), P) // G = B - A, reduced: it feeds the next add
          let f := add(g, sub(P, mulmod(rz, add(rz, rz), P))) // F = G - 2Z^2, < 2p
          let hh := sub(P, ab) // H = -A - B, <= p
          rx := mulmod(e, f, P)
          ry := mulmod(g, hh, P)
          rz := mulmod(f, g, P)
          rt := mulmod(e, hh, P)
        }

        let t := mload(0x40)
        let bits := or(and(shr(i, mload(add(t, 0x180))), 1), shl(1, and(shr(i, mload(add(t, 0x1a0))), 1)))
        if bits {
          // Unified addition with a cached addend (add-2008-hwcd-3, k = 2d). rx..rt are `< p`.
          let q := add(t, shl(7, sub(bits, 1)))
          let a := mulmod(add(ry, sub(P, rx)), mload(add(q, 0x20)), P) // operand < 2p
          let b := mulmod(add(ry, rx), mload(q), P) // operand < 2p
          let e := add(b, sub(P, a)) // < 2p
          let hh := add(b, a) // < 2p
          let c := mulmod(rt, mload(add(q, 0x40)), P)
          let d := mulmod(rz, mload(add(q, 0x60)), P)
          let f := add(d, sub(P, c)) // < 2p
          let g := add(d, c) // < 2p
          rx := mulmod(e, f, P)
          ry := mulmod(g, hh, P)
          rz := mulmod(f, g, P)
          rt := mulmod(e, hh, P)
        }
      }
    }
    result = Point({x: rx, y: ry, z: rz, t: rt});
  }

  /// @dev True iff `[8]point` is the identity, i.e. `point` lies in the torsion subgroup. Three
  ///      stack-only doublings with the same formula and bounds as `_doubleScalarMul`'s, then
  ///      `X == 0 && Y == Z`; the comparison is sound because all three are reduced `mulmod` outputs.
  ///      Internal for the same reason as `_doubleScalarMul`.
  function _isSmallOrder(Point memory point) internal pure returns (bool small) {
    assembly ("memory-safe") {
      let rx := mload(point)
      let ry := mload(add(point, 0x20))
      let rz := mload(add(point, 0x40))
      for { let i := 0 } lt(i, 3) { i := add(i, 1) } {
        let a := mulmod(rx, rx, P)
        let b := mulmod(ry, ry, P)
        let xy := add(rx, ry) // < 2p
        let ab := addmod(a, b, P)
        let e := add(mulmod(xy, xy, P), sub(P, ab)) // < 2p
        let g := addmod(b, sub(P, a), P)
        let f := add(g, sub(P, mulmod(rz, add(rz, rz), P))) // < 2p
        let hh := sub(P, ab) // <= p
        rx := mulmod(e, f, P)
        ry := mulmod(g, hh, P)
        rz := mulmod(f, g, P)
      }
      small := and(iszero(rx), eq(ry, rz))
    }
  }

  /// @dev Doubling for a = -1 (dbl-2008-hwcd).
  function _double(Point memory point) private pure returns (Point memory) {
    uint256 a = mulmod(point.x, point.x, P);
    uint256 b = mulmod(point.y, point.y, P);
    uint256 c = mulmod(2, mulmod(point.z, point.z, P), P);
    uint256 d = _neg(a); // a * A, with a = -1
    uint256 xy = addmod(point.x, point.y, P);
    uint256 e = addmod(mulmod(xy, xy, P), _neg(addmod(a, b, P)), P);
    uint256 g = addmod(d, b, P);
    uint256 f = addmod(g, _neg(c), P);
    uint256 h = addmod(d, _neg(b), P);

    return Point({x: mulmod(e, f, P), y: mulmod(g, h, P), z: mulmod(f, g, P), t: mulmod(e, h, P)});
  }

  /// @dev Unified addition for a = -1 with k = 2d (add-2008-hwcd-3).
  function _add(Point memory p1, Point memory p2) private pure returns (Point memory) {
    uint256 a = mulmod(addmod(p1.y, _neg(p1.x), P), addmod(p2.y, _neg(p2.x), P), P);
    uint256 b = mulmod(addmod(p1.y, p1.x, P), addmod(p2.y, p2.x, P), P);
    uint256 c = mulmod(mulmod(p1.t, D2, P), p2.t, P);
    uint256 d = mulmod(2, mulmod(p1.z, p2.z, P), P);
    uint256 e = addmod(b, _neg(a), P);
    uint256 f = addmod(d, _neg(c), P);
    uint256 g = addmod(d, c, P);
    uint256 h = addmod(b, a, P);

    return Point({x: mulmod(e, f, P), y: mulmod(g, h, P), z: mulmod(f, g, P), t: mulmod(e, h, P)});
  }

  function _base() private pure returns (Point memory) {
    return Point({x: BX, y: BY, z: 1, t: mulmod(BX, BY, P)});
  }

  function _identity() private pure returns (Point memory) {
    return Point({x: 0, y: 1, z: 1, t: 0});
  }

  function _neg(uint256 value) private pure returns (uint256) {
    return value == 0 ? 0 : P - value;
  }

  /// @notice Reverses byte order, taking a little-endian encoding to an integer or back.
  function fromLittleEndian(uint256 value) internal pure returns (uint256 v) {
    v = value;
    v = ((v & 0xFF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00) >> 8)
      | ((v & 0x00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF) << 8);
    v = ((v & 0xFFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000) >> 16)
      | ((v & 0x0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF) << 16);
    v = ((v & 0xFFFFFFFF00000000FFFFFFFF00000000FFFFFFFF00000000FFFFFFFF00000000) >> 32)
      | ((v & 0x00000000FFFFFFFF00000000FFFFFFFF00000000FFFFFFFF00000000FFFFFFFF) << 32);
    v = ((v & 0xFFFFFFFFFFFFFFFF0000000000000000FFFFFFFFFFFFFFFF0000000000000000) >> 64)
      | ((v & 0x0000000000000000FFFFFFFFFFFFFFFF0000000000000000FFFFFFFFFFFFFFFF) << 64);
    v = (v >> 128) | (v << 128);
  }

  /// @dev `base^exponent mod p` via the 0x05 precompile.
  function _modexp(uint256 base, uint256 exponent) private view returns (uint256 result) {
    uint256 modulus = P;
    assembly ("memory-safe") {
      let ptr := mload(0x40)
      mstore(ptr, 0x20) // base length
      mstore(add(ptr, 0x20), 0x20) // exponent length
      mstore(add(ptr, 0x40), 0x20) // modulus length
      mstore(add(ptr, 0x60), base)
      mstore(add(ptr, 0x80), exponent)
      mstore(add(ptr, 0xa0), modulus)
      if iszero(staticcall(gas(), 0x05, ptr, 0xc0, 0x00, 0x20)) { revert(0, 0) }
      result := mload(0x00)
    }
  }
}

