// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

/// @notice Minimal enumerable set helpers for the route/adapters registries.
library EnumerableSet {
  struct Set {
    bytes32[] values;
    mapping(bytes32 value => uint256 index) indexes;
  }

  struct AddressSet {
    Set inner;
  }

  struct Bytes32Set {
    Set inner;
  }

  function add(AddressSet storage _set, address _value) internal returns (bool) {
    return _add(_set.inner, bytes32(uint256(uint160(_value))));
  }

  function remove(AddressSet storage _set, address _value) internal returns (bool) {
    return _remove(_set.inner, bytes32(uint256(uint160(_value))));
  }

  function contains(AddressSet storage _set, address _value) internal view returns (bool) {
    return _contains(_set.inner, bytes32(uint256(uint160(_value))));
  }

  function length(AddressSet storage _set) internal view returns (uint256) {
    return _length(_set.inner);
  }

  function at(AddressSet storage _set, uint256 _index) internal view returns (address) {
    return address(uint160(uint256(_at(_set.inner, _index))));
  }

  function values(AddressSet storage _set) internal view returns (address[] memory _values) {
    uint256 count = _length(_set.inner);
    _values = new address[](count);
    for (uint256 i = 0; i < count; i++) {
      _values[i] = address(uint160(uint256(_at(_set.inner, i))));
    }
  }

  function add(Bytes32Set storage _set, bytes32 _value) internal returns (bool) {
    return _add(_set.inner, _value);
  }

  function remove(Bytes32Set storage _set, bytes32 _value) internal returns (bool) {
    return _remove(_set.inner, _value);
  }

  function contains(Bytes32Set storage _set, bytes32 _value) internal view returns (bool) {
    return _contains(_set.inner, _value);
  }

  function length(Bytes32Set storage _set) internal view returns (uint256) {
    return _length(_set.inner);
  }

  function at(Bytes32Set storage _set, uint256 _index) internal view returns (bytes32) {
    return _at(_set.inner, _index);
  }

  function values(Bytes32Set storage _set) internal view returns (bytes32[] memory _values) {
    uint256 count = _length(_set.inner);
    _values = new bytes32[](count);
    for (uint256 i = 0; i < count; i++) {
      _values[i] = _at(_set.inner, i);
    }
  }

  function _add(Set storage _set, bytes32 _value) private returns (bool) {
    if (_contains(_set, _value)) {
      return false;
    }

    _set.values.push(_value);
    _set.indexes[_value] = _set.values.length;
    return true;
  }

  function _remove(Set storage _set, bytes32 _value) private returns (bool) {
    uint256 valueIndex = _set.indexes[_value];
    if (valueIndex == 0) {
      return false;
    }

    uint256 index = valueIndex - 1;
    uint256 lastIndex = _set.values.length - 1;
    if (index != lastIndex) {
      bytes32 lastValue = _set.values[lastIndex];
      _set.values[index] = lastValue;
      _set.indexes[lastValue] = valueIndex;
    }

    _set.values.pop();
    delete _set.indexes[_value];
    return true;
  }

  function _contains(Set storage _set, bytes32 _value) private view returns (bool) {
    return _set.indexes[_value] != 0;
  }

  function _length(Set storage _set) private view returns (uint256) {
    return _set.values.length;
  }

  function _at(Set storage _set, uint256 _index) private view returns (bytes32) {
    return _set.values[_index];
  }
}

