// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

/// @title InboxAddress
/// @notice Counterfactual inbox address derivation helpers for supported chains
library InboxAddress {
  /// @dev Reference data for tooling and tests only. These MUST NOT be used to infer the runtime a
  /// deployment is executing on: the list cannot cover Tron networks it does not yet know about, and
  /// on any it misses every runtime-dependent branch (CREATE2 prefix, which owner slot authorizes,
  /// canonical address encoding) silently takes the EVM path. Use `LocalRuntime.detect()`, which
  /// derives the answer from the VM's own CREATE2 behaviour at construction.
  uint256 internal constant TRON_MAINNET_CHAIN_ID = 728126428;
  uint256 internal constant TRON_TESTNET_SHASTA_CHAIN_ID = 2494104990;
  uint256 internal constant TRON_DEVNET_CHAIN_ID = 3360022319;
  uint256 internal constant TRON_TESTNET_NILE_CHAIN_ID = 3448148188;

  string internal constant SOLANA_INBOX_SEED = "inbox";

  function computeEvm(address _deployer, bytes32 _salt, bytes32 _initCodeHash) internal pure returns (address _addr) {
    return address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff), _deployer, _salt, _initCodeHash)))));
  }

  function computeTron(address _deployer, bytes32 _salt, bytes32 _initCodeHash) internal pure returns (address _addr) {
    assembly ("memory-safe") {
      let ptr := mload(0x40)
      mstore(add(ptr, 0x40), _initCodeHash)
      mstore(add(ptr, 0x20), _salt)
      mstore(ptr, _deployer)
      let start := add(ptr, 0x0b)
      mstore8(start, 0x41)
      _addr := and(keccak256(start, 0x55), 0xffffffffffffffffffffffffffffffffffffffff)
    }
  }
}

