// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

/// @title InboxCall
/// @notice Packed calldata helper for PDA inboxes.
library InboxCall {
  function sendTransaction(address _inbox, address _target, uint256 _value, bytes memory _data)
    internal
    returns (bytes memory _result)
  {
    bool success;
    (success, _result) = trySendTransaction(_inbox, _target, _value, _data);

    assembly ("memory-safe") {
      if iszero(success) { revert(add(_result, 0x20), mload(_result)) }
    }
  }

  /// @dev Like `sendTransaction`, but returns `false` with the revert data instead of bubbling it.
  function trySendTransaction(address _inbox, address _target, uint256 _value, bytes memory _data)
    internal
    returns (bool _success, bytes memory _result)
  {
    assembly ("memory-safe") {
      let dataLength := mload(_data)
      let inputLength := add(dataLength, 0x40)
      let input := mload(0x40)

      mstore(input, _target)
      mstore(add(input, 0x20), _value)

      let src := add(_data, 0x20)
      let dst := add(input, 0x40)

      for { let end := add(src, dataLength) } lt(src, end) {
        src := add(src, 0x20)
        dst := add(dst, 0x20)
      } {
        mstore(dst, mload(src))
      }

      _success := call(gas(), _inbox, 0, input, inputLength, 0, 0)
      let size := returndatasize()

      _result := mload(0x40)
      mstore(_result, size)
      returndatacopy(add(_result, 0x20), 0, size)
      mstore(0x40, and(add(add(add(_result, 0x20), size), 0x1f), not(0x1f)))
    }
  }
}

