// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {LibOptim} from "../utils/LibOptim.sol";

/// @title InboxConfig
/// @author Agustin Aguilar
/// @notice Hashing utilities for counterfactual PDA inbox configurations
library InboxConfig {
  /// @notice Per-runtime inbox owners.
  /// @dev The owner is the identity that can control/recover the inbox on a given runtime. Because a
  /// single config is portable across chains, the inbox can come to rest on any runtime it bridges
  /// to, and only an owner expressed in that runtime's native key system can authorize there. A
  /// zero value means "no owner for this runtime", which makes bridging to that runtime disallowed.
  /// `evm`/`tron` are 20-byte secp256k1 addresses; `solana` is a 32-byte ed25519 pubkey.
  struct Owners {
    address evm;
    address tron;
    bytes32 solana;
  }

  /// @notice Counterfactual inbox configuration
  struct Config {
    Owners owners;
    uint256 destinationChainId;
    bytes32 destinationTo;
    bytes32 destinationToken;
    bytes destinationCalldata;
    uint256 maxSlippageBps;
    uint256 bridgeHopsRemaining;
  }

  // Pinned by spec/vectors/config-domain.json.
  uint256 private constant SOLANA_MAX_DESTINATION_CHAIN_ID = type(uint64).max;
  uint256 private constant SOLANA_MAX_BRIDGE_HOPS_REMAINING = type(uint8).max;
  uint256 private constant SOLANA_MAX_SLIPPAGE_BPS = type(uint16).max;
  uint256 private constant SOLANA_MAX_DESTINATION_CALLDATA_BYTES = 320;

  bytes32 private constant OWNERS_LEAF_TYPEHASH = keccak256("TrailsPdas.InboxConfiguration.owners");
  bytes32 private constant DESTINATION_CHAIN_ID_LEAF_TYPEHASH =
    keccak256("TrailsPdas.InboxConfiguration.destinationChainId");
  bytes32 private constant DESTINATION_TO_LEAF_TYPEHASH = keccak256("TrailsPdas.InboxConfiguration.destinationTo");
  bytes32 private constant DESTINATION_TOKEN_LEAF_TYPEHASH =
    keccak256("TrailsPdas.InboxConfiguration.destinationToken");
  bytes32 private constant DESTINATION_CALLDATA_LEAF_TYPEHASH =
    keccak256("TrailsPdas.InboxConfiguration.destinationCalldata");
  bytes32 private constant MAX_SLIPPAGE_BPS_LEAF_TYPEHASH = keccak256("TrailsPdas.InboxConfiguration.maxSlippageBps");
  bytes32 private constant BRIDGE_HOPS_REMAINING_LEAF_TYPEHASH =
    keccak256("TrailsPdas.InboxConfiguration.bridgeHopsRemaining");

  error InvalidEvmAddress(bytes32 _value);
  error DestinationChainIdExceedsRuntimeDomain(uint256 _chainId, uint8 _runtime, uint256 _value, uint256 _max);
  error BridgeHopsExceedRuntimeDomain(uint256 _chainId, uint8 _runtime, uint256 _value, uint256 _max);
  error MaxSlippageBpsExceedsRuntimeDomain(uint256 _chainId, uint8 _runtime, uint256 _value, uint256 _max);
  error DestinationCalldataExceedsRuntimeDomain(uint256 _chainId, uint8 _runtime, uint256 _value, uint256 _max);

  function addressToBytes32(address _account) internal pure returns (bytes32) {
    return bytes32(uint256(uint160(_account)));
  }

  function bytes32ToAddress(bytes32 _value) internal pure returns (address) {
    if (uint256(_value) > type(uint160).max) {
      revert InvalidEvmAddress(_value);
    }

    return address(uint160(uint256(_value)));
  }

  /// @notice Reverts when the config, with `_bridgeHopsRemaining` hops left, does not fit the Solana
  /// runtime domain (pinned by spec/vectors/config-domain.json).
  function requireSolanaDomain(Config calldata _config, uint256 _bridgeHopsRemaining, uint256 _chainId, uint8 _runtime)
    internal
    pure
  {
    if (_config.destinationChainId > SOLANA_MAX_DESTINATION_CHAIN_ID) {
      revert DestinationChainIdExceedsRuntimeDomain(
        _chainId, _runtime, _config.destinationChainId, SOLANA_MAX_DESTINATION_CHAIN_ID
      );
    }
    if (_bridgeHopsRemaining > SOLANA_MAX_BRIDGE_HOPS_REMAINING) {
      revert BridgeHopsExceedRuntimeDomain(_chainId, _runtime, _bridgeHopsRemaining, SOLANA_MAX_BRIDGE_HOPS_REMAINING);
    }
    if (_config.maxSlippageBps > SOLANA_MAX_SLIPPAGE_BPS) {
      revert MaxSlippageBpsExceedsRuntimeDomain(_chainId, _runtime, _config.maxSlippageBps, SOLANA_MAX_SLIPPAGE_BPS);
    }
    if (_config.destinationCalldata.length > SOLANA_MAX_DESTINATION_CALLDATA_BYTES) {
      revert DestinationCalldataExceedsRuntimeDomain(
        _chainId, _runtime, _config.destinationCalldata.length, SOLANA_MAX_DESTINATION_CALLDATA_BYTES
      );
    }
  }

  /// @notice Computes the configuration root
  /// @param _config The inbox configuration
  /// @return The configuration root
  function root(Config memory _config) internal pure returns (bytes32) {
    return _root(
      _config.owners,
      _config.destinationChainId,
      _config.destinationTo,
      _config.destinationToken,
      keccak256(_config.destinationCalldata),
      _config.maxSlippageBps,
      _config.bridgeHopsRemaining
    );
  }

  /// @notice Computes the configuration root straight from calldata, without copying the config to memory
  function rootCalldata(Config calldata _config) internal pure returns (bytes32) {
    return rootCalldata(_config, _config.bridgeHopsRemaining);
  }

  /// @notice Computes the configuration root of `_config` with `_bridgeHopsRemaining` in place of its own
  /// hop budget: the root the same config carries after a bridge.
  function rootCalldata(Config calldata _config, uint256 _bridgeHopsRemaining) internal pure returns (bytes32) {
    return _root(
      _config.owners,
      _config.destinationChainId,
      _config.destinationTo,
      _config.destinationToken,
      keccak256(_config.destinationCalldata),
      _config.maxSlippageBps,
      _bridgeHopsRemaining
    );
  }

  function _root(
    Owners memory _owners,
    uint256 _destinationChainId,
    bytes32 _destinationTo,
    bytes32 _destinationToken,
    bytes32 _destinationCalldataHash,
    uint256 _maxSlippageBps,
    uint256 _bridgeHopsRemaining
  ) private pure returns (bytes32) {
    bytes32 ownerLeaf = keccak256(abi.encode(OWNERS_LEAF_TYPEHASH, _owners.evm, _owners.tron, _owners.solana));
    bytes32 destinationChainIdLeaf = keccak256(abi.encode(DESTINATION_CHAIN_ID_LEAF_TYPEHASH, _destinationChainId));
    bytes32 destinationToLeaf = keccak256(abi.encode(DESTINATION_TO_LEAF_TYPEHASH, _destinationTo));
    bytes32 destinationTokenLeaf = keccak256(abi.encode(DESTINATION_TOKEN_LEAF_TYPEHASH, _destinationToken));
    bytes32 destinationCalldataLeaf =
      keccak256(abi.encode(DESTINATION_CALLDATA_LEAF_TYPEHASH, _destinationCalldataHash));
    bytes32 maxSlippageBpsLeaf = keccak256(abi.encode(MAX_SLIPPAGE_BPS_LEAF_TYPEHASH, _maxSlippageBps));
    bytes32 bridgeHopsRemainingLeaf = keccak256(abi.encode(BRIDGE_HOPS_REMAINING_LEAF_TYPEHASH, _bridgeHopsRemaining));

    return _hashNode(
      _hashNode(_hashNode(ownerLeaf, destinationChainIdLeaf), _hashNode(destinationToLeaf, destinationTokenLeaf)),
      _hashNode(_hashNode(destinationCalldataLeaf, maxSlippageBpsLeaf), bridgeHopsRemainingLeaf)
    );
  }

  function _hashNode(bytes32 _left, bytes32 _right) private pure returns (bytes32) {
    return LibOptim.fkeccak256(_left, _right);
  }
}

