// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {InboxAddress} from "./InboxAddress.sol";

/// @title LocalRuntime
/// @notice Self-verifying detection of the runtime a deployment is executing on.
/// @dev Trails needs to know whether it is running on the TVM or on an EVM chain, because the two
/// derive CREATE2 addresses differently (Tron replaces the `0xff` prefix with `0x41`). That single
/// answer also selects which owner slot authorizes an inbox and which canonical address encoding
/// bridge adapters emit.
///
/// The answer is derived from the VM's own CREATE2 behaviour instead of being asserted: deploy a
/// throwaway probe with a known salt and init code, then check which of the two address formulas
/// reproduces the address the VM actually used. A chain-id whitelist goes stale (and silently takes
/// the wrong branch on any Tron network missing from it); a constructor argument can be passed
/// wrong. This can do neither, and a VM matching *neither* formula fails the deployment instead of
/// mis-deriving every counterfactual inbox address for the lifetime of the contract.
///
/// Callers must resolve this ONCE, at construction, into an `immutable`. The answer feeds inbox
/// address derivation, so changing it later would re-derive every counterfactual address and orphan
/// funds already sent to previously-published ones.
library LocalRuntime {
  /// @dev Probe init code returning a single `STOP` byte as its runtime:
  ///
  ///   60 01    push1 0x01     // [runtime_size]
  ///   80       dup1           // [runtime_size, runtime_size]
  ///   60 0b    push1 0x0b     // [runtime_offset, runtime_size, runtime_size]
  ///   60 00    push1 0x00     // [0, runtime_offset, runtime_size, runtime_size]
  ///   39       codecopy       // [runtime_size]
  ///   60 00    push1 0x00     // [0, runtime_size]
  ///   f3       return         // return(0, 1)
  ///   00       <runtime>      // STOP
  ///
  /// Deliberately avoids `PUSH0` so the probe itself does not depend on the Shanghai opcode set.
  bytes internal constant PROBE_CREATION_CODE = hex"600180600b6000396000f300";

  /// @dev Salt for the probe. Domain separated from any configuration root, so probing can never
  /// consume an address an inbox would otherwise occupy.
  ///
  /// The probe address is not squattable: it is a CREATE2 address naming the probing contract as
  /// deployer, so nothing but that contract can ever deploy there. No fallback salt is needed — and
  /// none would help, because an address collision consumes all gas forwarded to the failed create.
  bytes32 internal constant PROBE_SALT = keccak256("TrailsPdas.LocalRuntime.probe.v1");

  error UnknownLocalRuntime(address _probe);
  error ProbeDeploymentFailed();

  /// @notice Decides which CREATE2 formula produced `_probe`.
  /// @dev Split out from the deployment so both branches are unit testable on a single VM.
  /// @return _isTron True when the address matches Tron's `0x41`-prefixed derivation.
  function resolve(address _deployer, bytes32 _salt, bytes32 _initCodeHash, address _probe)
    internal
    pure
    returns (bool _isTron)
  {
    if (_probe == InboxAddress.computeTron(_deployer, _salt, _initCodeHash)) {
      return true;
    }
    if (_probe == InboxAddress.computeEvm(_deployer, _salt, _initCodeHash)) {
      return false;
    }

    // Neither formula matched: this VM derives CREATE2 addresses in a way Trails cannot predict, so
    // no counterfactual inbox address it publishes would be reachable. Refuse to deploy.
    revert UnknownLocalRuntime(_probe);
  }

  /// @notice Deploys the probe and returns whether this VM uses Tron's CREATE2 derivation.
  /// @dev `internal`, so it is inlined and `address(this)` is the calling contract — the same
  /// deployer that will later create inboxes.
  function detect() internal returns (bool _isTron) {
    bytes memory creationCode = PROBE_CREATION_CODE;
    // `PROBE_SALT` is a constant expression, not a literal, so inline assembly cannot name it.
    bytes32 salt = PROBE_SALT;
    address probe;
    assembly ("memory-safe") {
      probe := create2(0, add(creationCode, 0x20), mload(creationCode), salt)
    }

    // Unreachable for a first-time deployment (see `PROBE_SALT`). Refuse rather than guess.
    if (probe == address(0)) {
      revert ProbeDeploymentFailed();
    }

    return resolve(address(this), PROBE_SALT, keccak256(creationCode), probe);
  }
}

src/libraries/Sha512.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

/// @title Sha512
/// @notice FIPS 180-4 SHA-512 over a memory byte string.
/// @dev The EVM exposes SHA-256 as a precompile but not SHA-512, and ed25519 is defined over
///      SHA-512: the challenge scalar is `SHA512(R || A || M)`. Verifying a Solana owner's signature
///      on EVM/Tron therefore needs the compression function in software.
///
///      The compression loop is Yul over full 256-bit words, with arithmetic taken modulo 2^64 by
///      masking (see the note in `hash`). The 80 round constants live in one packed `bytes`
///      constant and are read back eight bytes at a time, which keeps the deployed code far smaller
///      than 80 immediates would.
library Sha512 {
  /// @dev Round constants K[0..79]: the first 64 bits of the fractional parts of the cube roots of
  ///      the first eighty primes, packed big-endian, eight bytes each.
  bytes private constant K =
    hex"";

  /// @notice SHA-512 digest of `data`.
  /// @return hi The first 32 bytes of the digest.
  /// @return lo The last 32 bytes of the digest.
  function hash(bytes memory data) internal pure returns (bytes32 hi, bytes32 lo) {
    (uint256 blockPtr, uint256 blocks) = _pad(data);

    // Initial state H[0..7]: the first 64 bits of the fractional parts of the square roots of the
    // first eight primes.
    uint64 h0 = 0x6a09e667f3bcc908;
    uint64 h1 = 0xbb67ae8584caa73b;
    uint64 h2 = 0x3c6ef372fe94f82b;
    uint64 h3 = 0xa54ff53a5f1d36f1;
    uint64 h4 = 0x510e527fade682d1;
    uint64 h5 = 0x9b05688c2b3e6c1f;
    uint64 h6 = 0x1f83d9abfb41bd6b;
    uint64 h7 = 0x5be0cd19137e2179;

    uint64[80] memory w;
    bytes memory constants = K;
    // The compression loop runs in Yul on full words. Additions, xors and the `shl` half of a
    // rotation may leave garbage above bit 63, but carries and shifts left only move bits upward,
    // so the low 64 bits stay exact. Garbage would only corrupt a later `shr`, so every value that
    // is shifted right or stored is masked: the schedule words `w[i]`, the new `a` and `e`, and the
    // chaining values `h0..h7` (which are `uint64` locals and must stay clean). The remaining
    // state words are copies of those, hence clean, and `not(e)` is only ever and-ed with the
    // clean `g`.
    //
    // All sixteen state words stay on the stack. That is close to via-IR's limit: a caller that
    // inlines this next to many live locals of its own can hit "stack too deep", which is why the
    // differential test reaches it through an external call. `forge coverage --ir-minimum` (CI)
    // compiles it without the stack-to-memory mover, so the block loop walks a pointer to `end`
    // rather than keeping an index next to `blockPtr`; one more live slot there fails that build.
    // Moving the chaining values to memory would also fit, at ~5k gas per block.
    assembly ("memory-safe") {
      let kp := add(constants, 0x20)
      let wp := w
      let end := add(blockPtr, shl(7, blocks))
      for { let ptr := blockPtr } lt(ptr, end) { ptr := add(ptr, 0x80) } {
        for { let i := 0 } lt(i, 16) { i := add(i, 1) } {
          mstore(add(wp, shl(5, i)), shr(192, mload(add(ptr, shl(3, i)))))
        }
        for { let i := 16 } lt(i, 80) { i := add(i, 1) } {
          let x := mload(add(wp, shl(5, sub(i, 15))))
          let y := mload(add(wp, shl(5, sub(i, 2))))
          let s0 := xor(xor(or(shr(1, x), shl(63, x)), or(shr(8, x), shl(56, x))), shr(7, x))
          let s1 := xor(xor(or(shr(19, y), shl(45, y)), or(shr(61, y), shl(3, y))), shr(6, y))
          mstore(
            add(wp, shl(5, i)),
            and(
              add(add(add(mload(add(wp, shl(5, sub(i, 16)))), s0), mload(add(wp, shl(5, sub(i, 7))))), s1),
              0xffffffffffffffff
            )
          )
        }

        let a := h0
        let bb := h1
        let c := h2
        let d := h3
        let e := h4
        let f := h5
        let g := h6
        let hh := h7
        for { let i := 0 } lt(i, 80) { i := add(i, 1) } {
          let t1 :=
            add(
              add(
                add(
                  add(hh, xor(xor(or(shr(14, e), shl(50, e)), or(shr(18, e), shl(46, e))), or(shr(41, e), shl(23, e)))),
                  xor(and(e, f), and(not(e), g))
                ),
                shr(192, mload(add(kp, shl(3, i))))
              ),
              mload(add(wp, shl(5, i)))
            )
          let t2 :=
            add(
              xor(xor(or(shr(28, a), shl(36, a)), or(shr(34, a), shl(30, a))), or(shr(39, a), shl(25, a))),
              xor(xor(and(a, bb), and(a, c)), and(bb, c))
            )
          hh := g
          g := f
          f := e
          e := and(add(d, t1), 0xffffffffffffffff)
          d := c
          c := bb
          bb := a
          a := and(add(t1, t2), 0xffffffffffffffff)
        }
        h0 := and(add(h0, a), 0xffffffffffffffff)
        h1 := and(add(h1, bb), 0xffffffffffffffff)
        h2 := and(add(h2, c), 0xffffffffffffffff)
        h3 := and(add(h3, d), 0xffffffffffffffff)
        h4 := and(add(h4, e), 0xffffffffffffffff)
        h5 := and(add(h5, f), 0xffffffffffffffff)
        h6 := and(add(h6, g), 0xffffffffffffffff)
        h7 := and(add(h7, hh), 0xffffffffffffffff)
      }
    }

    hi = bytes32((uint256(h0) << 192) | (uint256(h1) << 128) | (uint256(h2) << 64) | uint256(h3));
    lo = bytes32((uint256(h4) << 192) | (uint256(h5) << 128) | (uint256(h6) << 64) | uint256(h7));
  }

  /// @dev Copies `data` into a fresh, padded buffer: `data || 0x80 || 0x00… || bitLength(uint128)`,
  ///      rounded up to a whole number of 128-byte blocks. The buffer carries 32 bytes of trailing
  ///      slack so the compression loop can read its last 8-byte word with a full `mload` without
  ///      touching memory it does not own.
  /// @return blockPtr Memory pointer to the first padded block.
  /// @return blocks Number of 128-byte blocks.
  function _pad(bytes memory data) private pure returns (uint256 blockPtr, uint256 blocks) {
    uint256 length = data.length;
    // One 0x80 byte plus the 16-byte length field must fit inside the last block.
    blocks = (length + 17 + 127) >> 7;
    uint256 paddedLength = blocks << 7;

    // Zero-initialized by `new`, so the interior padding needs no explicit writes.
    bytes memory padded = new bytes(paddedLength + 32);
    uint256 dataPtr;
    assembly ("memory-safe") {
      dataPtr := add(data, 0x20)
      blockPtr := add(padded, 0x20)
    }

    uint256 wholeWords = length & ~uint256(31);
    for (uint256 i = 0; i < wholeWords; i += 32) {
      assembly ("memory-safe") {
        mstore(add(blockPtr, i), mload(add(dataPtr, i)))
      }
    }
    if (length != wholeWords) {
      // Mask the tail so the copy cannot drag `data`'s own trailing slack into the padding.
      uint256 keep = ~uint256(0) << (8 * (32 - (length - wholeWords)));
      assembly ("memory-safe") {
        mstore(add(blockPtr, wholeWords), and(mload(add(dataPtr, wholeWords)), keep))
      }
    }

    // The trailing field is the 128-bit big-endian bit length. Writing it left-aligned at
    // `paddedLength - 16` keeps the `mstore` clear of the 0x80 marker (padding always leaves at
    // least 17 bytes) and spills its zero half into the buffer's own slack.
    uint256 bitLengthField = (length << 3) << 128;
    assembly ("memory-safe") {
      mstore8(add(blockPtr, length), 0x80)
      mstore(add(blockPtr, sub(paddedLength, 16)), bitLengthField)
    }
  }
}

src/libraries/SolanaPda.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

/// @title SolanaPda
/// @notice On-chain (EVM) replica of Solana's `find_program_address` / `create_program_address`.
/// @dev Solana derives a Program Derived Address by hashing the seeds, a bump byte, the program id
///      and the marker `"ProgramDerivedAddress"`, then requiring the result to be OFF the ed25519
///      curve (so no private key can exist for it). `find_program_address` walks the bump from 255
///      downward and returns the first off-curve candidate (the "canonical" bump).
///
///      The only non-trivial part on EVM is the off-curve test. A 32-byte value is a valid ed25519
///      point iff, interpreting the low 255 bits as the little-endian `y` coordinate, the value
///      `x^2 = (y^2 - 1) / (d*y^2 + 1)` is a quadratic residue in F_p (p = 2^255 - 19). We avoid a
///      modular inverse by using the identity QR(u/v) == QR(u*v) for v != 0 (they differ by the
///      square factor v^2), so a single Legendre symbol via the MODEXP precompile decides curve
///      membership. This matches curve25519-dalek's `CompressedEdwardsY::decompress().is_some()`,
///      which Solana uses for `bytes_are_curve_point`.
library SolanaPda {
  /// @dev Field prime p = 2^255 - 19.
  uint256 internal constant P = 0x7fffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffed;
  /// @dev Edwards curve constant d = -121665/121666 mod p.
  uint256 internal constant D = 0x52036cee2b6ffe738cc740797779e89800700a4d4141d8ab75eb4dca135978a3;
  /// @dev (p - 1) / 2, the Legendre symbol exponent.
  uint256 internal constant P_MINUS_1_DIV_2 = 0x3ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff6;
  /// @dev Low 255 bits; clears the ed25519 x-coordinate sign bit.
  uint256 internal constant MASK_255 = 0x7fffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff;
  /// @dev Trailing marker appended to every PDA preimage.
  bytes internal constant PDA_MARKER = "ProgramDerivedAddress";

  error NoCanonicalBump();

  /// @notice Returns true if `point` (raw 32 hashed bytes, little-endian ed25519 encoding) lies on
  ///         the ed25519 curve. On-curve points are NOT valid PDAs.
  function isOnCurve(bytes32 point) internal view returns (bool) {
    // Reverse to a little-endian integer and drop the sign bit -> y coordinate.
    uint256 y = _reverseBytes(point) & MASK_255;

    uint256 yy = mulmod(y, y, P);
    uint256 u = addmod(yy, P - 1, P); // y^2 - 1
    uint256 v = addmod(mulmod(D, yy, P), 1, P); // d*y^2 + 1

    if (v == 0) {
      return false; // no x exists -> off curve
    }

    uint256 uv = mulmod(u, v, P);
    if (uv == 0) {
      return true; // u == 0 -> x = 0, on curve (y = +/-1)
    }

    // Legendre symbol of u*v: 1 => quadratic residue (on curve), p-1 => non-residue (off curve).
    return _modexp(uv, P_MINUS_1_DIV_2, P) == 1;
  }

  /// @notice EVM equivalent of `create_program_address`: hash a fixed bump into the seeds.
  /// @param seeds The seed bytes concatenated (Solana hashes seeds back-to-back, no separators).
  /// @param bump  The bump seed byte.
  /// @param programId The owning program id (raw 32 bytes).
  /// @return ok  False when the derived address is on-curve (an invalid PDA).
  /// @return pda The derived address.
  function createProgramAddress(bytes memory seeds, uint8 bump, bytes32 programId)
    internal
    view
    returns (bool ok, bytes32 pda)
  {
    pda = sha256(abi.encodePacked(seeds, bump, programId, PDA_MARKER));
    ok = !isOnCurve(pda);
  }

  /// @notice EVM equivalent of `find_program_address`: walk bumps 255->0, return the first
  ///         off-curve (canonical) address. Reverts if none exists (cryptographically impossible).
  /// @dev The preimage `seeds||bump||programId||marker` is built once; each iteration only rewrites
  ///      the single bump byte in place and re-hashes via the sha256 precompile, avoiding a fresh
  ///      `abi.encodePacked` allocation+copy per step.
  function findProgramAddress(bytes memory seeds, bytes32 programId) internal view returns (bytes32 pda, uint8 bump) {
    bytes memory preimage = abi.encodePacked(seeds, uint8(0), programId, PDA_MARKER);
    uint256 bumpOffset = seeds.length; // byte index of the bump within the preimage payload

    for (uint256 b = 255;;) {
      bytes32 candidate = _sha256WithBump(preimage, bumpOffset, b);
      if (!isOnCurve(candidate)) {
        return (candidate, uint8(b));
      }
      if (b == 0) break;
      unchecked {
        --b;
      }
    }
    revert NoCanonicalBump();
  }

  /// @notice Canonical Associated Token Account for `(owner, tokenProgram, mint)`, derived in full
  ///         on-chain (no precomputed bump required).
  function findAssociatedTokenAccount(bytes32 owner, bytes32 tokenProgram, bytes32 mint, bytes32 associatedTokenProgram)
    internal
    view
    returns (bytes32 ata, uint8 bump)
  {
    return findProgramAddress(abi.encodePacked(owner, tokenProgram, mint), associatedTokenProgram);
  }

  /// @dev Reverse the byte order of a bytes32 (big-endian word <-> little-endian word).
  function _reverseBytes(bytes32 input) private pure returns (uint256 v) {
    v = uint256(input);
    v = ((v & 0xFF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00) >> 8)
      | ((v & 0x00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF) << 8);
    v = ((v & 0xFFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000) >> 16)
      | ((v & 0x0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF) << 16);
    v = ((v & 0xFFFFFFFF00000000FFFFFFFF00000000FFFFFFFF00000000FFFFFFFF00000000) >> 32)
      | ((v & 0x00000000FFFFFFFF00000000FFFFFFFF00000000FFFFFFFF00000000FFFFFFFF) << 32);
    v = ((v & 0xFFFFFFFFFFFFFFFF0000000000000000FFFFFFFFFFFFFFFF0000000000000000) >> 64)
      | ((v & 0x0000000000000000FFFFFFFFFFFFFFFF0000000000000000FFFFFFFFFFFFFFFF) << 64);
    v = (v >> 128) | (v << 128);
  }

  /// @dev Write `bump` into `preimage` at `bumpOffset`, then sha256 it via the 0x02 precompile.
  function _sha256WithBump(bytes memory preimage, uint256 bumpOffset, uint256 bump) private view returns (bytes32 out) {
    assembly ("memory-safe") {
      let dataPtr := add(preimage, 0x20)
      mstore8(add(dataPtr, bumpOffset), bump)
      if iszero(staticcall(gas(), 0x02, dataPtr, mload(preimage), 0x00, 0x20)) { revert(0, 0) }
      out := mload(0x00)
    }
  }

  /// @dev modexp via the 0x05 precompile for 32-byte base/exponent/modulus operands.
  function _modexp(uint256 base, uint256 exponent, uint256 modulus) private view returns (uint256 result) {
    assembly ("memory-safe") {
      let ptr := mload(0x40)
      mstore(ptr, 0x20) // base length
      mstore(add(ptr, 0x20), 0x20) // exponent length
      mstore(add(ptr, 0x40), 0x20) // modulus length
      mstore(add(ptr, 0x60), base)
      mstore(add(ptr, 0x80), exponent)
      mstore(add(ptr, 0xa0), modulus)
      if iszero(staticcall(gas(), 0x05, ptr, 0xc0, 0x00, 0x20)) { revert(0, 0) }
      result := mload(0x00)
    }
  }
}

