// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {RouteAsset} from "../interfaces/ISwapOracle.sol";

/// @title RouteScopeBase
/// @author Agustin Aguilar
/// @notice Chain-independent route-scope state: the active inbox and the set of route-accounted
/// assets that inbox callbacks are allowed to touch.
/// @dev The backing store is supplied by a chain-specific implementation of the primitives below:
/// ordinary storage on Shanghai targets (Tron, see RouteScopeStorage) and EIP-1153 transient
/// storage on Cancun targets (EVM, see TrailsPdasEvm). The seeding helpers and the authorization
/// policy that consumes this state live alongside the registry in RouteAdapters.
abstract contract RouteScopeBase {
  error RouteScopeAlreadyOpen(address _activeInbox);

  // ---------------------------------------------------------------------------
  // Chain-specific scope backend (implemented by RouteScopeStorage / the EVM transient override)
  // ---------------------------------------------------------------------------

  /// @dev Records the active inbox for the current route.
  function _setActiveInbox(address _inbox) internal virtual;

  /// @dev Returns the active inbox, or address(0) when no route is in scope.
  function _activeInbox() internal view virtual returns (address);

  /// @dev Idempotently marks a token as a route-accounted asset. Native (address(0)) is ignored.
  function _markRouteAsset(address _token) internal virtual;

  /// @dev Returns true when the token was marked for the active route.
  function _isRouteAsset(address _token) internal view virtual returns (bool);

  /// @dev Clears the active inbox and every route-asset marking. Transient backends must also drop
  /// the markings: they only self-clear at the end of the transaction, and a later route in the same
  /// transaction (possibly on the same inbox) must start with an empty asset set.
  function _clearRouteScope() internal virtual;

  // ---------------------------------------------------------------------------
  // Chain-independent policy
  // ---------------------------------------------------------------------------

  /// @notice Seeds the route context for the current execution.
  /// @dev Records the active inbox and current-chain ERC-20 asset tokens so inbox callbacks are
  /// scoped to this route. Native-token entries are skipped and guarded by the route balance invariant.
  /// At most one route scope is open at a time, so a nested begin reverts instead of reusing it.
  function _beginRouteContext(address _inbox, RouteAsset[] calldata _assets) internal {
    address activeInbox = _activeInbox();
    if (activeInbox != address(0)) {
      revert RouteScopeAlreadyOpen(activeInbox);
    }
    _setActiveInbox(_inbox);

    uint256 numAssets = _assets.length;
    for (uint256 i = 0; i < numAssets; i++) {
      if (_assets[i].chainId != block.chainid) {
        continue;
      }
      _markRouteAsset(_assets[i].token);
    }
  }

  /// @notice Clears the route context so batched calls cannot inherit stale callback authority.
  function _endRouteContext() internal {
    _clearRouteScope();
  }
}

