// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {RouteScopeBase} from "./RouteScopeBase.sol";

/// @title RouteScopeStorage
/// @author Agustin Aguilar
/// @notice Ordinary-storage scope backend for Shanghai targets (Tron) that lack EIP-1153 transient
/// storage. The scope is held in regular storage and explicitly cleared after each route; an
/// auxiliary token list is kept solely so the clear can enumerate the marked assets.
/// @dev The primitives are left `virtual` so the EVM deployment can override them with a transient
/// backend (see `evm/TrailsPdasEvm.sol`). When overridden, the storage slots declared here are
/// simply never written, which carries no runtime cost.
abstract contract RouteScopeStorage is RouteScopeBase {
  address private _scopeInbox;
  address[] private _scopeAssetList;
  mapping(address token => bool active) private _scopeAssets;

  function _setActiveInbox(address _inbox) internal virtual override {
    _scopeInbox = _inbox;
  }

  function _activeInbox() internal view virtual override returns (address) {
    return _scopeInbox;
  }

  function _markRouteAsset(address _token) internal virtual override {
    if (_token == address(0) || _scopeAssets[_token]) {
      return;
    }

    _scopeAssets[_token] = true;
    _scopeAssetList.push(_token);
  }

  function _isRouteAsset(address _token) internal view virtual override returns (bool) {
    return _scopeAssets[_token];
  }

  function _clearRouteScope() internal virtual override {
    uint256 numTokens = _scopeAssetList.length;
    for (uint256 i = 0; i < numTokens; i++) {
      delete _scopeAssets[_scopeAssetList[i]];
    }
    delete _scopeAssetList;
    delete _scopeInbox;
  }
}

