// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

/// @title LibOptim
/// @author Agustin Aguilar
/// @notice Library for optimized EVM operations
library LibOptim {
  /// @notice Computes the keccak256 hash of two 32-byte inputs.
  /// @dev Uses only scratch memory space.
  /// @param _a The first 32-byte input
  /// @param _b The second 32-byte input
  /// @return _c The keccak256 hash of both inputs
  function fkeccak256(bytes32 _a, bytes32 _b) internal pure returns (bytes32 _c) {
    assembly ("memory-safe") {
      mstore(0x00, _a)
      mstore(0x20, _b)
      _c := keccak256(0x00, 0x40)
    }
  }
}

